function scheduleReleaseSync(delay=60000){
  clearTimeout(releaseSyncTimer);
  releaseSyncTimer=setTimeout(verifyClientRelease,delay);
}

async function verifyClientRelease(){
  try{
    const response=await fetch('/api/health?release-sync='+Date.now(),{cache:'no-store',credentials:'same-origin'});
    const health=response.ok?await response.json():null,current=health?.version;
    if(current&&CLIENT_ASSET_BUILD&&current!==CLIENT_ASSET_BUILD){
      const unsafe=document.querySelector('.overlay')||document.querySelector('form[data-client-dirty="1"]')||/^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement?.tagName||'');
      if(unsafe){
        if(document.body.dataset.pendingRelease!==current){document.body.dataset.pendingRelease=current;toast(`NYSA CORE ${current} is ready and will load automatically after you finish the open form.`,7000);}
        return scheduleReleaseSync(5000);
      }
      const target=new URL('/',window.location.origin);target.searchParams.set('release',current);target.searchParams.set('from',CLIENT_ASSET_BUILD);window.location.replace(target);
      return;
    }
  }catch{}
  scheduleReleaseSync();
}

document.addEventListener('input',event=>event.target.closest('form')?.setAttribute('data-client-dirty','1'));
document.addEventListener('change',event=>event.target.closest('form')?.setAttribute('data-client-dirty','1'));

function refreshActiveWorkspace() {
  refreshAssignmentQueueNavigation();
  if (currentTab !== 'dashboard' || typeof window.refreshActiveCrmDashboard !== 'function') return;
  clearTimeout(workspaceRefreshTimer);
  workspaceRefreshTimer = setTimeout(() => window.refreshActiveCrmDashboard(), 120);
}

async function refreshAssignmentQueueNavigation({repeat=true}={}) {
  clearTimeout(assignmentQueueRefreshTimer);
  assignmentQueueRefreshTimer=null;
  const button=$('#assignment-queue-nav');
  if(!button||!ME)return;
  const leader=ME.role==='admin'||['manager','director'].includes(ME.jobRole),baseLabel=leader?'Assignment Queue':'Reassignment Claims';
  try{
    const {leads=[]}=await api('/crm/assignment-queue');
    const count=leads.length;
    button.textContent=`${baseLabel} (${count})`;
    button.classList.toggle('hidden',!leader&&count===0);
    button.setAttribute('aria-label',`${baseLabel}: ${count} pending`);
  }catch{
    button.textContent=baseLabel;
    button.classList.toggle('hidden',!leader);
  }finally{
    if(repeat&&ME)assignmentQueueRefreshTimer=setTimeout(()=>refreshAssignmentQueueNavigation({repeat:true}),60000);
  }
}

