async function api(path, opts = {}) {
  const { timeoutMs = 0, signal: callerSignal, refreshWorkspace = true, ...requestOpts } = opts;
  const timeoutController = timeoutMs > 0 ? new AbortController() : null;
  let timedOut = false;
  const forwardAbort = () => timeoutController?.abort(callerSignal?.reason);
  if (callerSignal && timeoutController) {
    if (callerSignal.aborted) forwardAbort();
    else callerSignal.addEventListener('abort', forwardAbort, { once: true });
  }
  const timeoutId = timeoutController ? setTimeout(() => { timedOut = true; timeoutController.abort(); }, timeoutMs) : null;
  let res;
  try {
    res = await fetch('/api' + path, {
    ...requestOpts,
    signal: timeoutController?.signal || callerSignal,
    cache: opts.cache || 'no-store',
    credentials: 'same-origin',
    headers: { 'Content-Type': 'application/json', ...(TOKEN ? { Authorization: 'Bearer ' + TOKEN } : {}), ...(requestOpts.headers || {}) },
    body: requestOpts.body ? JSON.stringify(requestOpts.body) : undefined
    });
  } catch (error) {
    if (timedOut && error?.name === 'AbortError') { const timeoutError = new Error('The request took too long. Please retry when ready; nothing was saved.'); timeoutError.code = 'client_timeout'; throw timeoutError; }
    throw error;
  } finally {
    if (timeoutId) clearTimeout(timeoutId);
    if (callerSignal && timeoutController) callerSignal.removeEventListener('abort', forwardAbort);
  }
  const data = await res.json().catch(() => ({}));
  if (res.status === 401 && ME) { logout(false); throw new Error('Session expired — please sign in again'); }
  if (!res.ok) { const error=new Error(data.error || 'Request failed'); error.status=res.status; error.data=data; throw error; }
  if (!['GET','HEAD'].includes(String(opts.method || 'GET').toUpperCase())) {document.querySelectorAll('form[data-client-dirty="1"]').forEach(form=>form.removeAttribute('data-client-dirty'));if(refreshWorkspace)refreshActiveWorkspace();}
  if (!['GET','HEAD'].includes(String(opts.method || 'GET').toUpperCase()))document.dispatchEvent(new CustomEvent('nysa:api-mutation-succeeded',{detail:{path,method:String(opts.method||'GET').toUpperCase()}}));
  if(String(opts.method||'GET').toUpperCase()==='POST'&&/\/requirements$/.test(path))document.dispatchEvent(new CustomEvent('nysa:requirements-saved',{detail:{path}}));
  const qualificationMatch=String(opts.method||'GET').toUpperCase()==='POST'&&path.match(/^\/crm\/leads\/([^/]+)\/qualification-assessments(?:\/[^/]+\/override)?$/);
  if(qualificationMatch)document.dispatchEvent(new CustomEvent('nysa:qualification-saved',{detail:{leadId:qualificationMatch[1]}}));
  return data;
}

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtPrice = (n, cur = 'AED') => esc(cur) + ' ' + Number(n).toLocaleString('en-US', { maximumFractionDigits: 0 });
const parseBusinessAmountInput=value=>{const text=String(value??'').trim().replace(/,/g,'').replace(/^AED\s*/i,'').replace(/\s*AED$/i,'').trim();if(!text)return null;const match=text.match(/^(\d+(?:\.\d+)?)\s*(K|M|B|THOUSAND|MILLION|BILLION)?$/i);if(!match)return NaN;const multiplier={K:1e3,THOUSAND:1e3,M:1e6,MILLION:1e6,B:1e9,BILLION:1e9}[String(match[2]||'').toUpperCase()]||1;return Number(match[1])*multiplier;};
const BUSINESS_AMOUNT_SELECTOR='[data-business-amount],input[name="budgetMin"],input[name="budgetMax"]';
function installBusinessAmountInputs(root){const inputs=[...(root.matches?.(BUSINESS_AMOUNT_SELECTOR)?[root]:[]),...(root.querySelectorAll?.(BUSINESS_AMOUNT_SELECTOR)||[])];for(const input of new Set(inputs)){input.type='text';input.inputMode='decimal';input.dataset.businessAmount='';let preview=input.parentElement.querySelector('[data-amount-preview]');if(!preview){preview=document.createElement('small');preview.dataset.amountPreview='';input.after(preview);}const update=()=>{const amount=parseBusinessAmountInput(input.value);preview.textContent=input.value.trim()?(Number.isFinite(amount)?`Interpreted as ${fmtPrice(amount)}`:'Enter an amount such as 2 M, 20K, 750K or 2000000'):'Examples: 2 M, 20K, 2.5m, 750K or 2000000';preview.style.color=Number.isFinite(amount)||!input.value.trim()?'var(--muted)':'var(--red)';};const normalize=()=>{const amount=parseBusinessAmountInput(input.value);if(Number.isFinite(amount))input.value=amount.toLocaleString('en-US',{maximumFractionDigits:2});};if(input.dataset.businessAmountInstalled!=='1'){input.dataset.businessAmountInstalled='1';normalize();input.addEventListener('input',update);input.addEventListener('blur',()=>{normalize();update();});}update();}}
function installOptionalDateClearControls(root){const names=['availabilityConfirmedAt','verificationExpiresAt','permitExpiresAt','agreementEffectiveFrom','agreementEffectiveTo','effectiveFrom','effectiveTo'];for(const name of names){const input=root.querySelector(`input[name="${name}"]`);if(!input)continue;let button=root.querySelector(`[data-clear-optional-date="${name}"]`);if(!button){const wrap=document.createElement('div');wrap.className='optional-date-control';input.before(wrap);wrap.append(input);button=document.createElement('button');button.type='button';button.className='btn btn-sm';button.dataset.clearOptionalDate=name;button.textContent='Clear';wrap.append(button);const help=document.createElement('small');help.textContent='Optional. Clear removes the recorded value when this form is saved.';wrap.after(help);}if(button.dataset.clearInstalled!=='1'){button.dataset.clearInstalled='1';button.addEventListener('click',()=>{input.value='';input.dispatchEvent(new Event('change',{bubbles:true}));});}}}
document.addEventListener('focusin',event=>{if(event.target.matches?.(BUSINESS_AMOUNT_SELECTOR))installBusinessAmountInputs(event.target);});
const customerSearchText=customer=>`${customer.id||''} ${customer.fullName||''} ${customer.email||''} ${customer.phone||''}`.toLocaleLowerCase();
function rankCustomerChoices(customers,search=''){const query=String(search).trim().toLocaleLowerCase();return [...customers].sort((a,b)=>{const aMatch=query&&customerSearchText(a).includes(query),bMatch=query&&customerSearchText(b).includes(query);if(aMatch!==bMatch)return aMatch?-1:1;return String(a.fullName||'').localeCompare(String(b.fullName||''),undefined,{sensitivity:'base'})||String(a.email||a.phone||'').localeCompare(String(b.email||b.phone||''),undefined,{sensitivity:'base'});});}
const fmtDate = (s) => s ? new Date(s.includes('T') ? s : s + 'Z').toLocaleString('en-GB', { day:'numeric', month:'short', year:'numeric', hour:'2-digit', minute:'2-digit' }) : '—';
const fmtMinutesFromSeconds=value=>{if(value===null||value===undefined||value==='')return '—';const minutes=Math.round(Number(value)/6)/10;return `${minutes} ${minutes===1?'minute':'minutes'}`;};
const fmtDateOnly=s=>{if(!s)return '—';const [y,m,d]=String(s).slice(0,10).split('-');return y&&m&&d?`${d}-${m}-${y}`:'—';};
const governedMatchReasonChoices=[['strong_fit','Strong fit'],['customer_preference','Customer preference'],['budget','Budget'],['location','Location'],['property_type','Property type'],['size_layout','Size / layout'],['payment_terms','Payment terms'],['timing','Timing'],['availability_clarification','Availability clarification'],['missing_information','Missing information'],['other','Other']];
const governedMatchReasonOptions=()=>governedMatchReasonChoices.map(([value,label])=>`<option value="${value}">${label}</option>`).join('');
function renderGovernedMatchActions(candidate,context={}){const prior=candidate.latestDecision,shortlistLabel=context.opportunityId?'Shortlist and assign to Opportunity':'Shortlist';return `<div class="governed-match-actions" data-governed-candidate="${candidate.id}" data-previous-decision="${prior?.id||''}"><div><b>Broker decision</b><small data-governed-decision-status>${prior?`${esc(prior.decision.replaceAll('_',' '))} · ${esc(prior.reasonNotes)}`:'No decision recorded'}</small></div><label>Controlled reason<select data-governed-decision-reason>${governedMatchReasonOptions()}</select></label><label>Decision notes<textarea data-governed-decision-notes maxlength="1000" placeholder="Record why this exact property is shortlisted, rejected or deferred"></textarea></label><div><button class="btn btn-primary btn-sm" data-governed-decision="shortlisted">${shortlistLabel}</button><button class="btn btn-sm" data-governed-decision="deferred">Defer</button><button class="btn btn-danger btn-sm" data-governed-decision="rejected">Reject</button></div><details><summary>Record immutable property feedback</summary><label>Evidence source<select data-governed-feedback-source><option value="customer_reported">Customer reported</option><option value="broker_observed">Broker observed</option><option value="viewing_feedback">Viewing feedback</option></select></label><label>Outcome<select data-governed-feedback-outcome><option value="interested">Interested</option><option value="not_suitable">Not suitable</option><option value="more_options">More options requested</option><option value="viewing_requested">Viewing requested</option><option value="information_required">Information required</option></select></label><label>Controlled reason<select data-governed-feedback-reason>${governedMatchReasonOptions()}</select></label><label>Feedback notes<textarea data-governed-feedback-notes maxlength="2000" placeholder="Record the property-level evidence without rewriting this run"></textarea></label><button class="btn btn-sm" data-governed-feedback-save>Record feedback</button><div data-governed-feedback-status><small>${candidate.feedback?.length?`${candidate.feedback.length} immutable feedback record${candidate.feedback.length===1?'':'s'}`:'No feedback recorded'}</small></div></details></div>`;}
function bindGovernedMatchActions(root,leadId,run,reload,onAssignmentChanged){root.querySelectorAll('[data-governed-candidate]').forEach(form=>{const candidateId=form.dataset.governedCandidate,endpoint=`/crm/leads/${leadId}/inventory-matching-runs/${run.id}/candidates/${candidateId}`;form.querySelectorAll('[data-governed-decision]').forEach(button=>button.addEventListener('click',async()=>{const reasonNotes=form.querySelector('[data-governed-decision-notes]').value.trim();if(!reasonNotes)return toast('Record decision notes');form.querySelectorAll('button').forEach(x=>x.disabled=true);try{const assignToOpportunity=button.dataset.governedDecision==='shortlisted'&&Boolean(run.opportunityId),response=await api(`${endpoint}/decisions`,{method:'POST',body:{decision:button.dataset.governedDecision,reasonCode:form.querySelector('[data-governed-decision-reason]').value,reasonNotes,expectedPreviousDecisionId:form.dataset.previousDecision||null,assignToOpportunity,requestId:assignToOpportunity?crypto.randomUUID():null}});form.dataset.previousDecision=response.decision.id;form.querySelector('[data-governed-decision-status]').textContent=`${response.decision.decision.replaceAll('_',' ')} · ${response.decision.reasonNotes}`;form.querySelector('[data-governed-decision-notes]').value='';toast(response.createsInventoryAssignment?`Inventory assigned to this Opportunity until ${fmtDate(response.assignment.expiresAt)}`:response.assignmentDelinked?'Inventory assignment delinked; immutable decision and history retained':response.decision.decision==='shortlisted'?'Shortlist decision recorded; open an Opportunity to create an assignment':'Immutable broker decision recorded',8000);if(response.createsInventoryAssignment||response.assignmentDelinked){onAssignmentChanged?.(response);if(reload)await reload();}}catch(err){toast(err.message,9000);}finally{form.querySelectorAll('button').forEach(x=>x.disabled=false);}}));form.querySelector('[data-governed-feedback-save]')?.addEventListener('click',async buttonEvent=>{const notes=form.querySelector('[data-governed-feedback-notes]').value.trim();if(!notes)return toast('Record property feedback notes');buttonEvent.currentTarget.disabled=true;try{await api(`${endpoint}/feedback`,{method:'POST',body:{decisionId:form.dataset.previousDecision||null,sourceKind:form.querySelector('[data-governed-feedback-source]').value,outcome:form.querySelector('[data-governed-feedback-outcome]').value,reasonCode:form.querySelector('[data-governed-feedback-reason]').value,notes}});form.querySelector('[data-governed-feedback-notes]').value='';form.querySelector('[data-governed-feedback-status]').innerHTML='<small>Immutable feedback recorded against this exact run</small>';toast('Property feedback recorded as governed evidence');}catch(err){toast(err.message,7000);}finally{buttonEvent.currentTarget.disabled=false;}});});}
const handoverQuarterValue=date=>{const value=String(date||'').slice(0,10);if(!/^\d{4}-\d{2}-\d{2}$/.test(value))return'';const [year,month]=value.split('-').map(Number);return `${year}-Q${Math.floor((month-1)/3)+1}`;};
const handoverQuarterDate=value=>{const match=String(value||'').match(/^(\d{4})-Q([1-4])$/);return match?`${match[1]}-${String((Number(match[2])-1)*3+1).padStart(2,'0')}-01`:'';};
function normalizeOfferPartyControls(root,opportunity){
  const primaryRole=opportunity.transactionType==='Rental'?'tenant':'buyer',primaryLabel=primaryRole==='tenant'?'Tenant':'Buyer';
  for(const select of root.querySelectorAll('select[name="counterpartyRole"],select[name="proposerRole"]')){
    for(const option of select.options)if(option.value==='customer'){option.value=primaryRole;option.textContent=primaryLabel;}
    if(![...select.options].some(option=>option.value==='buyer'))select.add(new Option('Buyer','buyer'));
    if(![...select.options].some(option=>option.value==='tenant'))select.add(new Option('Tenant','tenant'));
  }
  root.querySelectorAll('.offer-event-form').forEach(form=>form.classList.add('offer-party-aligned'));
}
const handoverQuarterOptions=date=>{const selected=handoverQuarterValue(date),start=new Date().getFullYear()-1;return Array.from({length:12},(_,yearOffset)=>start+yearOffset).flatMap(year=>[1,2,3,4].map(quarter=>{const value=`${year}-Q${quarter}`;return`<option value="${value}" ${value===selected?'selected':''}>Q${quarter} ${year}</option>`;})).join('');};
const handoverLabel=l=>l.handoverStatus==='ready'||l.handoverDate==='Ready'?'Ready':l.handoverStatus==='expected'||/^\d{4}-\d{2}-\d{2}$/.test(String(l.handoverDate||''))?`Expected ${handoverQuarterValue(l.handoverExpectedDate||l.handoverDate).replace('-',' ')}`:'To be confirmed';
const canPost = () => ME && (ME.role === 'admin' || ME.role === 'internal_broker' || (ME.role === 'partner_broker' && ME.canPost === 1));
const canCreateListing = () => canPost() && (ME.role==='admin'||['listing_agent','admin_assistant','manager'].includes(ME.jobRole));
const canEditListing = (l) => ME && (ME.role === 'admin' || ME.jobRole==='admin_assistant' || l.postedBy === ME.id);
const isViewer = () => ME && ME.role === 'viewer';

function toast(msg, duration = 3200) {
  const t = document.createElement('div');
  t.className = 'toast'; t.textContent = msg;
  document.body.appendChild(t);
  setTimeout(() => t.remove(), duration);
}

