function bindPasswordToggles(root=app){root.querySelectorAll('[data-password-toggle]').forEach(button=>button.addEventListener('click',()=>{const input=document.getElementById(button.dataset.passwordToggle);if(!input)return;const show=input.type==='password';input.type=show?'text':'password';button.textContent=show?'Hide':'Show';button.setAttribute('aria-label',`${show?'Hide':'Show'} password`);input.focus();}));}
function setAuthBusy(form,busy){const button=form?.querySelector('button[type="submit"],button:not([type])');if(!button)return;if(busy){button.dataset.label=button.textContent;button.textContent='Please wait…';button.disabled=true;form.setAttribute('aria-busy','true');}else{button.textContent=button.dataset.label||button.textContent;button.disabled=false;form.removeAttribute('aria-busy');}}
function renderSetup(setupEnabled) {
  app.innerHTML = authPage(`
    <div>${setupEnabled ? '<div class="info-msg">Create the first administrator account. This screen closes permanently after setup.</div>' : '<div class="error-msg">Add BOOTSTRAP_KEY in the Node.js application environment variables, then restart the application.</div>'}</div>
    <form id="setup-form">
      <div class="field"><label for="setup-name">Full name</label><input id="setup-name" name="name" required autocomplete="name"></div>
      <div class="field"><label for="setup-email">Email address</label><input id="setup-email" name="email" type="email" required autocomplete="email"></div>
      <div class="field"><label for="setup-phone">Phone</label><input id="setup-phone" name="phone" autocomplete="tel"></div>
      <div class="field auth-password"><label for="setup-password">Administrator password</label><input id="setup-password" name="password" type="password" required minlength="12" autocomplete="new-password"><button class="auth-password-toggle" type="button" data-password-toggle="setup-password" aria-label="Show administrator password">Show</button></div>
      <div class="field auth-password"><label for="setup-key">Private setup key</label><input id="setup-key" name="bootstrapKey" type="password" required autocomplete="off"><button class="auth-password-toggle" type="button" data-password-toggle="setup-key" aria-label="Show setup key">Show</button></div>
      <button class="btn btn-primary auth-submit" ${setupEnabled ? '' : 'disabled'}>Create administrator</button>
    </form>
  `,{eyebrow:'Initial setup',title:'Configure NYSA CORE',description:'Create the first governed administrator account.'});
  bindPasswordToggles();
  $('#setup-form').addEventListener('submit', async (e) => {
    e.preventDefault();
    const showErr = (m) => $('#auth-msg').innerHTML = `<div class="error-msg">${esc(m)}</div>`;
    const form=e.currentTarget;setAuthBusy(form,true);
    try {
      const { broker } = await api('/auth/setup', { method: 'POST', body: Object.fromEntries(new FormData(e.target)) });
      resetClientSessionState();
      ME = broker;
      renderShell();
    } catch (err) { showErr(err.message);setAuthBusy(form,false); }
  });
}

