  $('#external-mapping-create')?.addEventListener('submit',async event=>{event.preventDefault();try{await api('/external-publication-mappings',{method:'POST',body:Object.fromEntries(new FormData(event.target))});toast('Draft connector mapping version created');renderExternalPortalListings();}catch(error){toast(error.message,7000);}});
