function showDialogError(dialog,msg){
  let panel=dialog.querySelector('.dialog-error');
  if(!panel){panel=document.createElement('div');panel.className='dialog-error';const heading=dialog.querySelector('.modal h2');heading?.insertAdjacentElement('afterend',panel);}
  panel.innerHTML=`<b>Action could not be completed</b><span>${esc(msg)}</span>`;
  panel.scrollIntoView({behavior:'smooth',block:'center'});
  panel.focus();
}

