    $('#lx-queue').querySelectorAll('.listing-queue-row').forEach((row,index)=>{const listing=action[index],next=listing.nextStep||{};const title=listing.inventoryHeadline||listing.project;row.querySelector('.recent-main b').textContent=title;row.querySelector('.recent-main small').textContent=`Project: ${listing.project} · ${listing.area} · ${LISTING_WORKFLOW_LABELS[listing.workflowStatus]||listing.workflowStatus}`;const button=row.querySelector('[data-listing-queue-action]');if(listing.workflowStatus==='draft'&&next.buttonLabel==='Continue draft')button.dataset.destination='detail';});
    $('#lx-queue').querySelectorAll('img.listing-queue-cover').forEach(img=>img.addEventListener('error',()=>{const fallback=document.createElement('span');fallback.className='listing-queue-cover listing-queue-cover-empty';fallback.textContent='Cover unavailable';img.replaceWith(fallback);},{once:true}));
    $('#lx-queue').querySelectorAll('[data-listing-queue-action]').forEach(button=>button.addEventListener('click',()=>openListingQueueAction(button.dataset.listingQueueAction,button.dataset.destination)));
