async function openListingQueueAction(id,destination){
  if(destination==='detail')return openDetail(id);
  let listing;try{listing=await api('/listings/'+id);}catch(err){return toast(`Listing action not opened: ${err.message}`);}
  if(destination==='media')return openPropertyMedia(listing);
  const focusField=destination==='availability'?'availabilityConfirmedAt':destination==='verification'?'verificationStatus':null;
  return openListingForm(listing,{focusField});
}

const isProposalCorrectionTask=t=>t.taskType==='proposal_correction'&&t.proposalId&&t.proposalVersionId;
const isLeaveApprovalTask=t=>t.taskType==='leave_approval'&&t.leaveApplicationId;
const isLeadAssignmentTask=t=>t.taskType==='lead_assignment'&&t.leadId;
const isMarketingMaterialTask=t=>['marketing_material_review','marketing_material_follow_up'].includes(t.taskType)&&t.marketingMaterialVersionId;
const taskDescription=t=>isLeadAssignmentTask(t)?`<div class="task-summary lead-assignment-task"><b>${esc(t.subject)}</b><small>${esc(t.details)}</small><small>This task closes automatically when the queued Lead is assigned.</small></div>`:isLeaveApprovalTask(t)?`<div class="task-summary leave-approval-task"><b>Leave approval · ${esc(t.leaveApplicantName)}</b><small><b>Leave type:</b> ${esc(t.leaveTypeLabel)}</small><small>${esc(t.leaveStartDate)} to ${esc(t.leaveEndDate)} · ${Number(t.leaveWorkingUnits)} working day(s)</small><small><b>Reason for leave:</b> Open Review leave (assigned approver only)</small></div>`:isMarketingMaterialTask(t)?`<div class="task-summary marketing-material-task"><b>Marketing material review · ${esc(t.marketingMaterialTitle)}</b><small>${esc(t.materialReference)} · Version ${Number(t.marketingMaterialVersionNumber)}</small><small>${esc(t.details||'Review every assigned channel and its current dependencies.')}</small></div>`:isProposalCorrectionTask(t)?`<div class="proposal-correction-task"><b>Proposal changes requested</b><span>${esc(t.proposalNumber)} · Returned Version ${Number(t.returnedVersionNumber)}</span><div class="proposal-return-reason"><strong>Reviewer remarks</strong><p>${esc(t.returnReason||t.details||'No reason recorded')}</p></div><small>Returned by ${esc(t.returnedByName||'authorized reviewer')} · ${fmtDate(t.returnedAt)}</small><small>Revise this same proposal. The task completes automatically after the corrected immutable version is generated.</small></div>`:`<div class="task-summary"><b>${esc(t.subject)}</b><small>${esc(t.details||'No additional instructions')}</small></div>`;
const taskActions=t=>isLeadAssignmentTask(t)?`<button class="btn btn-sm" data-task-lead="${t.leadId}">Open lead</button> <button class="btn btn-primary btn-sm" data-open-assignment-task>Open assignment queue</button>`:isLeaveApprovalTask(t)?`${t.status==='open'?`<button class="btn btn-sm" data-task-start="${t.id}">Start</button>`:''}${!['completed','cancelled'].includes(t.status)?` <button class="btn btn-primary btn-sm" data-leave-review="${t.leaveApplicationId}">Review leave</button>`:''}`:isMarketingMaterialTask(t)?`${t.status==='open'?`<button class="btn btn-sm" data-task-start="${t.id}">Start</button>`:''} <button class="btn btn-primary btn-sm" data-marketing-review="${t.marketingMaterialVersionId}">Review material</button>`:isProposalCorrectionTask(t)?`<button class="btn btn-sm" data-task-pdf="${t.id}">View returned PDF</button> <button class="btn btn-primary btn-sm" data-task-revise="${t.id}">Revise same proposal</button>`:`<button class="btn btn-sm" data-task-lead="${t.leadId}">Open lead</button> ${t.status==='open'?`<button class="btn btn-sm" data-task-start="${t.id}">Start</button>`:''}${!['completed','cancelled'].includes(t.status)?`<button class="btn btn-primary btn-sm" data-task-complete="${t.id}">Complete</button> <button class="btn btn-sm" data-task-cancel="${t.id}">Cancel</button>`:''}`;
async function bindTaskActions(root,tasks,reload){
  root.querySelectorAll('[data-open-assignment-task]').forEach(button=>button.onclick=()=>openAssignmentQueue());
  root.querySelectorAll('[data-marketing-review]').forEach(button=>button.onclick=()=>window.openMarketingMaterialReview?.(button.dataset.marketingReview,reload));
  root.querySelectorAll('[data-task-lead]').forEach(b=>b.addEventListener('click',()=>openLead(b.dataset.taskLead)));
  const change=async(id,status)=>{const outcome=status==='in_progress'?null:prompt(status==='completed'?'Completion outcome (required)':'Cancellation reason (required)');if(status!=='in_progress'&&!outcome)return;try{await api(`/crm/tasks/${id}`,{method:'PATCH',body:{status,outcome}});toast(status==='in_progress'?'Task started':status==='completed'?'Task completed':'Task cancelled');reload();}catch(err){toast(err.message);}};
  root.querySelectorAll('[data-task-start]').forEach(b=>b.addEventListener('click',()=>change(b.dataset.taskStart,'in_progress')));root.querySelectorAll('[data-task-complete]').forEach(b=>b.addEventListener('click',()=>change(b.dataset.taskComplete,'completed')));root.querySelectorAll('[data-task-cancel]').forEach(b=>b.addEventListener('click',()=>change(b.dataset.taskCancel,'cancelled')));
  root.querySelectorAll('[data-task-pdf]').forEach(b=>b.addEventListener('click',()=>{const t=tasks.find(x=>x.id===b.dataset.taskPdf);if(t)openProposalPdfReview({id:t.proposalVersionId,versionNumber:t.returnedVersionNumber,documentVersionId:t.documentVersionId,status:'changes_requested',reviewComment:t.returnReason});}));
  root.querySelectorAll('[data-task-revise]').forEach(b=>b.addEventListener('click',async()=>{const t=tasks.find(x=>x.id===b.dataset.taskRevise);if(!t)return;try{if(t.status==='open')await api(`/crm/tasks/${t.id}`,{method:'PATCH',body:{status:'in_progress'}});const{lead}=await api(`/crm/leads/${t.leadId}`);openProposals(lead,null,t.proposalId);}catch(err){toast(`Proposal correction not opened: ${err.message}`,7000);}}));
  root.querySelectorAll('[data-leave-review]').forEach(b=>b.addEventListener('click',()=>window.openLeaveReview?.(b.dataset.leaveReview,reload)));
}
async function renderTaskWorkspace(target){
  target.innerHTML=`<div class="filterbar embedded-task-filter"><div class="filter-grid"><div><label>Status</label><select id="task-bucket"><option value="open">Open and in progress</option><option value="overdue">Overdue</option><option value="today">Due today</option><option value="upcoming">Upcoming</option><option value="completed">Completed</option></select></div><div class="span2"><label>Search my tasks</label><input id="task-search" type="search" placeholder="Action, reason, customer or lead"></div></div><div class="filter-actions"><button class="btn btn-primary btn-sm" id="task-refresh">Refresh</button><span id="task-count" class="result-count"></span></div></div><div id="task-workspace"><div class="loading-state">Loading your tasks...</div></div>`;
  let tasks=[];
  const draw=()=>{const q=$('#task-search').value.trim().toLowerCase(),rows=tasks.filter(t=>!q||[t.subject,t.details,t.returnReason,t.proposalNumber,t.contactName,t.leadTitle,t.leaveApplicantName,t.leaveTypeLabel,t.marketingMaterialTitle,t.materialReference,t.priority,t.status].some(x=>String(x||'').toLowerCase().includes(q)));$('#task-count').textContent=`${rows.length} task${rows.length===1?'':'s'}`;const target=$('#task-workspace');target.innerHTML=`<div class="pipeline-table-wrap"><table><tr><th>Priority</th><th>Action required</th><th>Context</th><th>Status</th><th>Due</th><th>Actions</th></tr>${rows.map(t=>`<tr class="${isProposalCorrectionTask(t)?'proposal-correction-row':isLeaveApprovalTask(t)?'leave-approval-row':isMarketingMaterialTask(t)?'marketing-material-row':''}"><td><span class="pill">${esc(t.priority)}</span></td><td>${taskDescription(t)}</td><td>${isLeaveApprovalTask(t)?'Workforce · leave':isMarketingMaterialTask(t)?'Marketing · governed release':`${esc(t.contactName)}<small>${esc(t.leadTitle)}</small>`}</td><td>${esc(t.status.replaceAll('_',' '))}</td><td>${fmtDate(t.dueAt)}</td><td class="task-workspace-actions">${taskActions(t)}</td></tr>`).join('')||'<tr><td colspan="6">No tasks match this view.</td></tr>'}</table></div>`;bindTaskActions(target,rows,load);};
  const load=async()=>{try{({tasks}=await api(`/crm/tasks?mine=1&bucket=${encodeURIComponent($('#task-bucket').value)}`));draw();}catch(err){$('#task-workspace').textContent=err.message;}};
  $('#task-refresh').addEventListener('click',load);$('#task-bucket').addEventListener('change',load);$('#task-search').addEventListener('input',draw);load();
}
window.renderTaskWorkspace=renderTaskWorkspace;
