  const kycCard=`<article><span>KYC and contact verification</span><b>${esc((customer.kycStatus||'unverified').replaceAll('_',' '))}</b><small>${customer.idDocumentType?`${esc(customer.idDocumentType.replaceAll('_',' '))} ending ${esc(customer.idDocumentLast4||'----')}`:'Identity reference not recorded'}${customer.idDocumentExpiry?' · expires '+esc(customer.idDocumentExpiry):''}</small><small><b>Pre-KYC email evidence:</b> ${esc(customer.emailCredibilityStatus?customer.emailCredibilityStatus.replaceAll('_',' '):'not checked')} · ${esc(professional.label||'Professional match not checked')}${professional.profile?.company?` · ${esc(professional.profile.company)}`:''}. Advisory only; this does not verify identity.</small>${customer.email&&data.canRefreshContactCredibility?'<button class="btn btn-sm" type="button" data-refresh-contact-credibility>Run pre-KYC email check</button>':''}${customer.email&&data.canRefreshContactCredibility&&data.contactCredibilityConfig?.apolloConfigured?'<button class="btn btn-sm" type="button" data-run-apollo-professional>Run paid Apollo professional check</button><small>Uses a paid Apollo request only when selected.</small>':''}${evidenceDetails}</article>`;
  const o=recordWorkspace(`<div class="modal lead-modal"><button class="close-x">×</button><div class="detail-head"><div><div class="eyebrow">CUSTOMER MASTER</div><h2>${esc(customer.fullName)}</h2><p>Customer ID ${esc(customer.id)}</p></div></div><div class="customer-summary-grid"><article><span>Primary contact</span><b>${esc(customer.email||'Email missing')}</b><small>${esc(customer.phone||'Phone missing')} · ${esc(customer.preferredChannel||'Preferred channel missing')}</small></article>
${kycCard}<article><span>Consent</span><b>${data.effectiveConsent?'Granted':'Not granted'}</b><small>${data.restricted?'Communication restricted':'No active restriction'}</small></article></div>${canMaintain?`<details open><summary>Customer profile</summary><form id="customer-profile-form" class="form-grid compact-form"><div class="span2"><label>Customer full name *</label><input name="fullName" required value="${esc(customer.fullName)}"></div><div><label>Customer postal address</label><input name="postalAddress" value="${esc(customer.postalAddress||'')}"></div><div><label>Email *</label><input name="email" type="email" required value="${esc(customer.email||'')}"></div><div><label>Phone *</label><input name="phone" required value="${esc(customer.phone||'')}"></div><div><label>Preferred channel</label><select name="preferredChannel"><option value="">Not confirmed</option>${['WhatsApp','Phone','Email','SMS'].map(x=>`<option ${customer.preferredChannel===x?'selected':''}>${x}</option>`).join('')}</select></div><button class="btn btn-primary btn-sm">Save customer profile</button></form></details><details><summary>KYC and verification</summary><form id="customer-kyc-form" class="form-grid compact-form"><div><label>ID type</label><select name="idDocumentType"><option value="">Not recorded</option><option value="passport" ${customer.idDocumentType==='passport'?'selected':''}>Passport</option><option value="emirates_id" ${customer.idDocumentType==='emirates_id'?'selected':''}>Emirates ID</option></select></div><div><label>Final four characters only</label><input name="idDocumentLast4" maxlength="4" pattern="[A-Za-z0-9]{4}" value="${esc(customer.idDocumentLast4||'')}"></div><div><label>Expiry date</label><input name="idDocumentExpiry" type="date" value="${esc(customer.idDocumentExpiry||'')}"></div><div><label>KYC status</label><select name="kycStatus">${['unverified','pending_review','verified','expired','rejected'].map(x=>`<option value="${x}" ${customer.kycStatus===x?'selected':''}>${x.replaceAll('_',' ')}</option>`).join('')}</select></div><div class="span2"><label>Internal KYC notes</label><input name="kycNotes" value="${esc(customer.kycNotes||'')}"></div><button class="btn btn-primary btn-sm">Save KYC review</button></form></details><details><summary>Channels and customer roles</summary><div class="customer-related-list">${channels.map(x=>`<div><b>${esc(x.channelKind)} · ${esc(x.usageLabel)}</b><span>${esc(x.rawValue)} · ${esc(x.verificationStatus)}</span></div>`).join('')||'No channels recorded.'}</div><form id="customer-channel-form" class="admin-toolbar"><div><label>Channel</label><select name="channelKind"><option>Phone</option><option>Email</option></select></div><div><label>Label</label><input name="usageLabel" value="Additional"></div><div><label>Value</label><input name="rawValue" required></div><button class="btn btn-sm">Add channel</button></form><p><b>Roles:</b> ${roles.map(r=>esc(r.roleCode)).join(', ')||'None'}</p><form id="customer-role-form" class="admin-toolbar"><div><label>Add customer role</label><select name="roleCode"><option>buyer</option><option>seller</option><option>landlord</option><option>tenant</option><option>investor</option><option>other</option></select></div><button class="btn btn-sm">Add role</button></form></details>`:''}<details open><summary>Related leads (${leads.length})</summary><div class="customer-related-list">${leads.map(l=>`<button data-related-lead="${l.id}"><b>${esc(l.title)}</b><span>${esc(l.businessType)} · ${esc(l.stage)} · ${esc(l.temperature)}</span></button>`).join('')||'No related leads.'}</div></details><details><summary>Private linked documents (${documents.length})</summary><div class="customer-related-list">${documents.map(d=>`<div><b>${esc(d.title)}</b><span>${esc(d.documentType)} · ${esc(d.status)} · ${fmtDate(d.createdAt)}</span></div>`).join('')||'No accessible linked documents.'}</div></details></div>`,{type:'customer',id,returnTab:'customers'});
  $('#customer-role-form option[value="developer"]',o)?.remove();
  const canReviewKyc=Boolean(data.canReviewKyc),canDecideKyc=canReviewKyc&&!canMaintain&&customer.kycStatus==='pending_review',customerHead=$('.detail-head',o),customerDocumentSummary=[...o.querySelectorAll('summary')].find(x=>x.textContent.startsWith('Private linked documents'));
