  try {
    [{ lead, activities, stageHistory, intakeEvidence, latestAssignment, qualificationGuidance,canWrite }, { staff }, { teams }, { listings },operatingContext] = await Promise.all([
      api('/crm/leads/' + id),api('/crm/staff'),api('/crm/teams'),api('/listings?sort=newest&status=Available&pageSize=100'),api(`/crm/leads/${id}/operating-context`)]);
  } catch(err) { return toast(err.message); }
