    const mediaForm=$('#media-form',content),reviewFiles=()=>{if(!mediaForm)return;const files=Array.from(mediaForm.elements.files.files),review=$('#media-file-review',content),button=$('#media-batch-submit',content);review.innerHTML=files.length?`<b>${files.length} photo${files.length===1?'':'s'} selected</b><ol>${files.map(file=>`<li>${esc(file.name)} · ${Math.ceil(file.size/1024)} KB</li>`).join('')}</ol>`:'No photos selected.';button.textContent=files.length?`${reviewer?.automaticApproval?'Upload and approve':'Send for approval'} ${files.length} photo${files.length===1?'':'s'}`:uploadLabel;};
