    cards.forEach((card,index)=>{const item=media[index],isPhoto=item.mediaKind==='image';card.dataset.mediaId=item.id;card.insertAdjacentHTML('afterbegin',isPhoto?`<div class="property-media-thumbnail"><img src="/api/crm/property-media/${item.id}/thumbnail" alt="${esc(item.fileName)}"><span>${esc(item.fileName)}</span></div>`:`<div class="property-media-thumbnail media-video-tile"><span>Property video</span><b>${esc(item.fileName)}</b></div>`);const summarySmall=card.querySelector('.property-media-summary small');summarySmall?.insertAdjacentHTML('beforebegin',`<small class="property-media-file-name">Original file: ${esc(item.fileName)}</small>`);const orderFact=card.querySelector('.property-media-facts span:nth-child(2)');if(orderFact)orderFact.innerHTML=`<b>Photo position</b>${isPhoto?photoMedia.findIndex(photo=>photo.id===item.id)+1:'Not applicable'}`;const edit=card.querySelector('[data-edit-media]');if(edit)edit.textContent='Edit title and caption';const cover=card.querySelector('[data-cover-media]');if(cover)cover.textContent='Make cover photo';const actions=card.querySelector('.property-media-actions');if(canMaintain&&actions){const photoIndex=photoMedia.findIndex(photo=>photo.id===item.id);if(isPhoto){const positionOptions=photoMedia.map((photo,position)=>`<option value="${position+1}" ${photo.id===item.id?'selected':''}>${position+1}</option>`).join('');actions.insertAdjacentHTML('beforeend',`<span class="photo-order-controls"><button class="btn btn-sm photo-arrow" type="button" data-move-media="${item.id}" data-direction="earlier" title="Move photo up one position" aria-label="Move photo up one position" ${photoIndex===0?'disabled':''}>&#8593;</button><button class="btn btn-sm photo-arrow" type="button" data-move-media="${item.id}" data-direction="later" title="Move photo down one position" aria-label="Move photo down one position" ${photoIndex===photoMedia.length-1?'disabled':''}>&#8595;</button><label>Move to position <select data-media-position="${item.id}">${positionOptions}</select></label><button class="btn btn-sm" type="button" data-place-media="${item.id}">Move</button></span>`);}actions.insertAdjacentHTML('beforeend',`<button class="btn btn-sm btn-danger" data-delete-media="${item.id}">Delete unused media</button>`);}});
    cards.forEach((card,index)=>{const item=media[index],actions=card.querySelector('.property-media-actions');if(item.derivedFromMediaId)card.querySelector('.property-media-summary>div')?.insertAdjacentHTML('beforeend',`<small class="pf-derivative-badge">PF-ready derivative · original preserved · ${esc(item.derivativeTransform?.watermarkStyle==='nysa_text_v1'?'NYSA watermark':'no watermark')}</small>`);if(canMaintain&&actions&&item.mediaKind==='image'&&item.approvalStatus==='approved'&&!item.derivedFromMediaId)actions.insertAdjacentHTML('beforeend',`<button class="btn btn-sm" type="button" data-pf-derivative="${item.id}">Create PF-ready copy</button>`);});
