    let selectedFiles=[],selectedIssues=[],selectionVersion=0,previewUrls=[];
    if(mediaForm){mediaForm.elements.displayOrder.value=String(photoMedia.length);mediaForm.elements.displayOrder.closest('div')?.classList.add('hidden');}
    const syncSelectedInput=()=>{if(!mediaForm)return;const transfer=new DataTransfer();selectedFiles.forEach(file=>transfer.items.add(file));mediaForm.elements.files.files=transfer.files;};
    const enhancedReviewFiles=async()=>{if(!mediaForm)return;const version=++selectionVersion,review=$('#media-file-review',content),button=$('#media-batch-submit',content);previewUrls.forEach(URL.revokeObjectURL);previewUrls=[];if(!selectedFiles.length){selectedIssues=[];review.innerHTML='No photos selected.';button.disabled=false;button.textContent=uploadLabel;return;}review.innerHTML='<div class="loading-state">Checking selected photos and duplicates...</div>';const existingByHash=new Map(media.map(item=>[item.fileHash,item])),seen=new Map(),rows=[];selectedIssues=[];for(let index=0;index<selectedFiles.length;index++){const file=selectedFiles[index],hash=await fileSha256(file),existing=existingByHash.get(hash),prior=seen.get(hash),validation=await validatePropertyMediaFile(file),issue=existing?`Already uploaded as ${existing.fileName} (${existing.title})`:prior!==undefined?`Duplicate of selected photo ${prior+1}`:validation||null;if(!seen.has(hash))seen.set(hash,index);if(issue)selectedIssues.push({index,issue});const url=URL.createObjectURL(file);previewUrls.push(url);rows.push(`<article class="selected-photo-card ${issue?'has-error':''}"><img src="${url}" alt="${esc(file.name)}"><div><b>${index+1}. ${esc(file.name)}</b><small>${Math.ceil(file.size/1024)} KB</small>${issue?`<span class="selected-photo-error">${esc(issue)}</span>`:'<span class="selected-photo-ready">Ready to upload</span>'}</div><button class="btn btn-sm" type="button" data-remove-selected="${index}">Remove</button></article>`);}if(version!==selectionVersion)return;review.innerHTML=`<b>${selectedFiles.length} photo${selectedFiles.length===1?'':'s'} selected</b><div class="selected-photo-grid">${rows.join('')}</div>${selectedIssues.length?'<p class="error-text">Remove the highlighted duplicate or invalid photo before uploading. Other selected photos remain available.</p>':''}`;button.disabled=selectedIssues.length>0;button.textContent=selectedIssues.length?'Resolve highlighted photos before upload':`${reviewer?.automaticApproval?'Upload and approve':'Send for approval'} ${selectedFiles.length} photo${selectedFiles.length===1?'':'s'}`;};
