const openProposalsLegacy=openProposals;
async function openProposalsConfigured(lead,listings){
  await openProposalsLegacy(lead,listings);
  const vf=document.querySelector('.overlay:last-of-type #proposal-version-form');
  if(!vf)return;
  let templates=[];try{({templates}=await api('/crm/proposal-templates'));}catch(err){return toast(err.message);}
  const inputBox=document.createElement('div');inputBox.id='configured-proposal-inputs';inputBox.className='span3 form-grid';
  vf.querySelector('button[type="submit"]').before(inputBox);
  const selectedTemplate=()=>templates.find(t=>t.templateType===vf.elements.proposalId.selectedOptions[0]?.dataset.templateType);
  const renderInputs=()=>{
    const sections=selectedTemplate()?.configuration?.sections||[],labels=sections.map(x=>x.label);
    if(labels.length)vf.elements.sections.innerHTML=labels.map(x=>`<option selected>${esc(x)}</option>`).join('');
    const prompts=sections.filter(x=>x.source==='agent_input');
    inputBox.innerHTML=prompts.length?`<h3 class="span3">Information to complete for this proposal</h3>${prompts.map(x=>`<div class="span3"><label>${esc(x.label)}${x.mandatory?' *':''}</label>${x.helpText?`<small>${esc(x.helpText)}</small>`:''}<textarea data-proposal-input="${esc(x.code)}" ${x.mandatory?'required':''}></textarea></div>`).join('')}`:'<small>This template uses mapped system information and does not require additional agent text.</small>';
    for(const name of ['highlights','suitability','assumptions']){const field=vf.elements[name];if(field)field.parentElement.hidden=prompts.some(x=>x.code===name);}
  };
  vf.elements.proposalId.addEventListener('change',renderInputs);renderInputs();
  vf.addEventListener('submit',async e=>{
    e.preventDefault();e.stopImmediatePropagation();
    const f=Object.fromEntries(new FormData(vf));
    f.listingIds=Array.from(vf.elements.listingIds.selectedOptions).map(x=>x.value);f.mediaIds=Array.from(vf.elements.mediaIds.selectedOptions).map(x=>x.value);f.sections=Array.from(vf.elements.sections.selectedOptions).map(x=>x.value);f.financialScenarioId=f.financialScenarioId||null;
    f.inputs=Object.fromEntries(Array.from(vf.querySelectorAll('[data-proposal-input]')).map(x=>[x.dataset.proposalInput,x.value.trim()]));
    for(const name of ['highlights','suitability','assumptions'])if(f.inputs[name]!==undefined)f[name]=f.inputs[name];
    try{await api(`/crm/proposals/${f.proposalId}/versions`,{method:'POST',body:f});toast('Proposal PDF generated');vf.closest('.overlay').remove();openProposals(lead,listings);}catch(err){toast(err.message);}
  },true);
}
openProposals=openProposalsConfigured;

