/* ============ LISTINGS ============ */
const opts = (arr, sel) => arr.map(o => `<option value="${esc(o)}" ${o === sel ? 'selected' : ''}>${esc(o)}</option>`).join('');
async function loadListingAreas({force=false}={}){if(listingAreas&&!force)return listingAreas;const result=await api('/crm/areas');listingAreas=result.areas||[];return listingAreas;}

function renderListings() {
  const listingExecutive=ME.jobRole==='listing_agent';
  $('#view').innerHTML = `
  ${listingExecutive?`<section class="dashboard-head listing-workspace-head"><div><div class="eyebrow">NYSA CORE / INTERNAL INVENTORY</div><h2>My Inventory workspace</h2><p>Step 1: maintain Inventory. Step 2: complete mandatory verification or an authorized exemption, which activates it. Step 3 (optional): create an external Listing and submit it to a portal.</p></div><div class="dashboard-actions"><button class="btn btn-sm" id="listing-workspace-dashboard">Back to my dashboard</button><button class="btn btn-sm" id="listing-intake-queue">Integration / import intake</button><button class="btn btn-primary btn-sm" id="listing-workspace-new">Create Inventory draft</button></div></section><section id="listing-workspace-strip" class="listing-workspace-strip"><div class="loading-state">Loading my Inventory queues...</div></section>`:''}
  <div class="filterbar">
    <div class="filter-grid">
      ${listingExecutive?`<div><label>Inventory view</label><select id="f-workspace-scope"><option value="mine">My working inventory</option><option value="approved">Approved company inventory</option></select></div>`:''}
      <div><label>Search</label><input id="f-q" placeholder="Project, developer, area…"></div>
      <div><label>Area</label><select id="f-area"><option value="">All maintained areas</option></select></div>
      <div><label>Community</label><input id="f-community" placeholder="Building, district or sub-community"></div>
      <div><label>Property type</label><select id="f-type"><option value="">Any</option>${opts(PROPERTY_TYPES)}</select></div>
      <div><label>Bedrooms</label><select id="f-beds"><option value="">Any</option>${opts(BEDROOMS)}</select></div>
      <div><label>Min budget (AED)</label><input id="f-min" type="number" min="0" placeholder="0"></div>
      <div><label>Max budget (AED)</label><input id="f-max" type="number" min="0" placeholder="Any"></div>
      <div><label>Payment plan</label><select id="f-plan"><option value="">Any</option>${opts(PAYMENT_PLANS)}</select></div>
      <div><label>Status</label><select id="f-status"><option value="">Any</option>${opts(STATUSES, 'Available')}</select></div>
      ${(ME.role==='admin'||ME.jobRole==='manager'||listingExecutive)?`<div><label>Workflow</label><select id="f-workflow"><option value="">Any</option>${Object.entries(LISTING_WORKFLOW_LABELS).map(([value,label])=>`<option value="${value}">${label}</option>`).join('')}</select></div>`:''}
      <div><label>Exclusivity</label><select id="f-tier"><option value="">Any</option>${opts(TIERS)}</select></div>
      <div><label>Developer</label><input id="f-dev" placeholder="e.g. Emaar"></div>
      <div><label>Handover before</label><input id="f-hb" type="date"></div>
      <div><label>Handover after</label><input id="f-ha" type="date"></div>
    </div>
    <div class="filter-actions">
      <button class="btn btn-primary btn-sm" id="f-apply">Apply filters</button>
      <button class="btn btn-sm" id="f-reset">Reset</button>
      <select id="f-sort" style="width:auto">
        <option value="newest">Newest first</option>
        <option value="price_asc">Price: low → high</option>
        <option value="price_desc">Price: high → low</option>
        <option value="discount">Biggest discount vs reference</option>
        <option value="handover">Nearest handover</option>
      </select>
      ${canCreateListing() ? '<button class="btn btn-sm" id="inventory-import-btn">Upload Inventory Excel</button><button class="btn btn-primary btn-sm" id="add-listing-btn">+ Add Inventory</button>' : ''}
      <span class="result-count" id="f-count"></span>
    </div>
  </div>
  <div id="results" class="grid"></div>`;

  const restartListingSearch=()=>{loadListings.page=1;loadListings();};
  $('#f-apply').addEventListener('click', restartListingSearch);
  $('#f-reset').addEventListener('click', () => { renderListings(); });
  $('#f-sort').addEventListener('change', restartListingSearch);
  $('#f-workspace-scope')?.addEventListener('change',()=>{const own=$('#f-workspace-scope').value==='mine';$('#f-workflow').disabled=!own;if(!own)$('#f-workflow').value='approved';restartListingSearch();});
  $('#add-listing-btn')?.addEventListener('click', () => openListingForm());
  $('#inventory-import-btn')?.addEventListener('click',openInventoryImport);
  $('#listing-workspace-new')?.addEventListener('click',()=>openListingForm());
  $('#listing-intake-queue')?.addEventListener('click',openListingIntakeQueue);
  $('#listing-workspace-dashboard')?.addEventListener('click',()=>switchTab('dashboard'));
  $('#view').querySelectorAll('input').forEach(i => i.addEventListener('keydown', e => { if (e.key === 'Enter') restartListingSearch(); }));
  if(listingExecutive)api('/listings-workspace').then(({counts})=>{$('#listing-workspace-strip').innerHTML=[['My drafts',counts.drafts],['Awaiting review',counts.awaitingReview],['Changes requested',counts.changesRequested],['Media incomplete',counts.incompleteMedia],['Intake attention',counts.intakeAttention]].map(([label,value])=>`<div><b>${Number(value||0)}</b><span>${label}</span></div>`).join('');}).catch(err=>{$('#listing-workspace-strip').textContent=err.message;});
  loadListingAreas().then(areas=>{$('#f-area').innerHTML='<option value="">All maintained areas</option>'+areas.map(area=>`<option value="${area.id}">${esc(area.businessLabel)} · ${esc(area.emirate)}</option>`).join('');loadListings();}).catch(err=>toast(`Areas not loaded: ${err.message}`));
}

async function openListingIntakeQueue(){
  const o=overlay(`<div class="modal lead-modal"><button class="close-x">×</button><h2>Integration / import intake</h2><p class="tool-note">Provider events create reviewable Draft listings only. Failed mappings and possible duplicates stay here for controlled review; an integration never publishes or overwrites approved inventory.</p><div id="listing-intake-events" class="loading-state">Loading intake events...</div></div>`);
  const load=async()=>{try{const{events}=await api('/listing-intake');$('#listing-intake-events',o).innerHTML=events.length?`<table><tr><th>Provider / external record</th><th>Event / mapping</th><th>Status</th><th>Assigned</th><th>Action</th></tr>${events.map(x=>`<tr><td><b>${esc(x.providerCode)}</b><small>${esc(x.externalRecordId)}</small></td><td class="mono">${esc(x.eventId)}<small>${esc(x.mappingVersion)}</small></td><td><span class="badge">${esc(x.status.replaceAll('_',' '))}</span><small>${esc(x.errorDetail||'Draft preserved for NYSA review')}</small></td><td>${esc(x.assignedToName)}<small>${fmtDate(x.receivedAt)}</small></td><td>${x.listingId?`<button class="btn btn-sm" data-open-intake-listing="${x.listingId}">Review draft</button>`:x.duplicateListingId?`<button class="btn btn-sm" data-open-intake-listing="${x.duplicateListingId}">Review existing</button>`:['failed','unmapped'].includes(x.status)?`<button class="btn btn-sm" data-replay-listing-intake="${esc(x.eventId)}" data-replay-listing-provider="${esc(x.providerCode)}">Retry after correction</button>`:'—'}</td></tr>`).join('')}</table>`:'<div class="empty compact">No integration or import events are assigned to you.</div>';o.querySelectorAll('[data-open-intake-listing]').forEach(b=>b.onclick=()=>{o.remove();openDetail(b.dataset.openIntakeListing);});o.querySelectorAll('[data-replay-listing-intake]').forEach(b=>b.onclick=async()=>{try{await api(`/listing-intake/${encodeURIComponent(b.dataset.replayListingProvider)}/${encodeURIComponent(b.dataset.replayListingIntake)}/replay`,{method:'POST',body:{}});toast('Intake event replayed into a Draft');load();}catch(err){toast(err.message);load();}});}catch(err){$('#listing-intake-events',o).textContent=err.message;}};load();
}

function openInventoryImport(){
  let reviewed=null;
  const o=overlay(`<div class="modal lead-modal"><button class="close-x">×</button><div class="detail-head"><div><div class="eyebrow">INTERNAL INVENTORY / GOVERNED BULK INTAKE</div><h2>Upload Inventory from Excel</h2><p>Use one reusable template for bulk entry now and future CRM migrations. CORE reviews every row before saving and creates Draft Inventory only.</p></div></div>
    <section class="proposal-readiness blocked"><b>No automatic activation</b><span>Imported rows are Drafts. A NYSA user must review ownership, authority, availability and verification before matching can use them.</span></section>
    <section class="proposal-readiness"><b>Duplicate identity control</b><span>Every row requires Unit Reference/Unit Number, Building, Size, Community and governed Area. Exact matches link to the existing NYSA Inventory and never create a second master.</span></section>
    <div class="form-grid compact-form"><div><label>Source system code *</label><input id="inventory-import-source" value="inventory_excel" pattern="[a-z][a-z0-9_]*" required><small>Use one stable name per source, such as current_crm. This prevents the same source record being imported twice.</small></div><div><label>Completed Excel workbook *</label><input id="inventory-import-file" type="file" accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"></div><div><label>Default originating agent</label><select id="inventory-import-originating-agent"><option value="">Use each row's agent reference</option></select><small>Select explicitly when every blank row belongs to one agent.</small></div><div><label>Default responsible agent</label><select id="inventory-import-responsible-agent"><option value="">Same as originating agent</option></select><small>Each workbook row may override this default.</small></div><div class="span3"><label>Active Area codes for the area_code column</label><div id="inventory-import-areas" class="tool-note">Loading maintained Area codes…</div></div><div class="span3 modal-actions"><a class="btn btn-sm" href="/templates/inventory-import-template.xlsx" download>Download approved Excel template</a><button class="btn btn-primary btn-sm" id="inventory-import-review" type="button">Review workbook</button></div></div>
    <div id="inventory-import-summary" class="tool-note">Nothing has been uploaded.</div><div id="inventory-import-preview"></div>
    <form id="inventory-import-commit" class="form-grid compact-form hidden"><div class="span2"><label>Business reason for this import *</label><input name="reason" required placeholder="CRM Test matching inventory preparation"></div><button class="btn btn-primary btn-sm">Create reviewed Draft Inventory</button></form></div>`);
  const summary=$('#inventory-import-summary',o),preview=$('#inventory-import-preview',o),commit=$('#inventory-import-commit',o);
  loadListingAreas({force:true}).then(areas=>{$('#inventory-import-areas',o).innerHTML=areas.map(area=>`<span class="badge"><b>${esc(area.stableCode)}</b> · ${esc(area.businessLabel)}</span>`).join(' ')||'No active Areas are maintained.';}).catch(error=>{$('#inventory-import-areas',o).textContent=`Area codes unavailable: ${error.message}`;});
  api('/inventory-agents').then(({inventoryAgents})=>{const options=inventoryAgents.map(agent=>`<option value="${esc(agent.email)}">${esc(agent.name)} · ${esc(agent.email)}</option>`).join('');$('#inventory-import-originating-agent',o).insertAdjacentHTML('beforeend',options);$('#inventory-import-responsible-agent',o).insertAdjacentHTML('beforeend',options);}).catch(error=>{summary.textContent=`Assignable agents could not be loaded: ${error.message}`;summary.className='tool-note error-text';});
  const render=result=>{
    reviewed=result;const invalid=result.rows.filter(row=>row.errors.length),ready=result.rows.filter(row=>!row.errors.length&&!row.skipped),matched=result.rows.filter(row=>row.matchedListingId);
    summary.textContent=`Review complete: ${ready.length} ready; ${matched.length} matched existing Inventory; ${result.skippedCount} skipped; ${invalid.length} invalid. ${invalid.length?'Zero records can be imported until every invalid row is corrected.':ready.length?'Ready rows can now be created as Draft Inventory.':'There are no new rows to import.'}`;
    summary.className=`tool-note ${invalid.length?'error-text':'success-text'}`;commit.classList.toggle('hidden',invalid.length>0||ready.length===0);
    preview.innerHTML=`<div class="fee-table-wrap"><table><tr><th>Excel row</th><th>Source record</th><th>Inventory</th><th>Duplicate identity</th><th>Matched CORE Inventory</th><th>NYSA attribution</th><th>Review result</th></tr>${result.rows.map(row=>`<tr class="${row.errors.length?'import-row-error':row.skipped?'import-row-skipped':'import-row-valid'}"><td>${row.rowNumber}</td><td class="mono">${esc(row.externalRecordId||'—')}</td><td><b>${esc(row.inventoryHeadline||'—')}</b><small>${esc(row.project||'—')} · ${esc(row.propertyType||'—')}</small></td><td><b>${esc(row.unitReference||'Unit missing')} · ${esc(row.building||'Building missing')}</b><small>${row.sizeSqft||'Size missing'} sqft · ${esc(row.community||'Community missing')} · ${esc(row.areaCode||'Area missing')}</small></td><td>${row.matchedListingId?`<button class="btn btn-sm" data-open-import-match="${esc(row.matchedListingId)}">Open ${esc(row.matchedInventoryReference)}</button><small>Status: ${esc(row.matchedInventoryStatus)}</small>`:'No exact match'}</td><td><b>Origin: ${esc(row.originatingAgentName||row.originatingAgentReference||'Not resolved')}</b><small>Responsible: ${esc(row.responsibleAgentName||row.responsibleAgentReference||'Not resolved')}</small></td><td>${row.errors.length?esc(row.errors.join(' · ')):row.skipped?esc(row.skipReason):`Ready as Draft${row.ownerName?' with owner':' for owner enrichment'}${row.warnings.length?` · Review: ${esc(row.warnings.join(' · '))}`:''}`}</td></tr>`).join('')}</table></div>`;
    preview.querySelectorAll('[data-open-import-match]').forEach(button=>button.addEventListener('click',()=>{o.remove();openDetail(button.dataset.openImportMatch);}));
  };
  $('#inventory-import-review',o).addEventListener('click',async()=>{
    const file=$('#inventory-import-file',o).files[0],sourceCode=$('#inventory-import-source',o).value.trim().toLowerCase();reviewed=null;commit.classList.add('hidden');preview.innerHTML='';
    if(!file)return toast('Choose the completed Inventory Excel template first');
    if(!file.name.toLowerCase().endsWith('.xlsx'))return toast('Choose an .xlsx workbook created from the approved Inventory template');
    if(file.size<1||file.size>5242880)return toast('Inventory workbook must be between 1 byte and 5 MB');
    summary.textContent='Reviewing every Inventory row…';summary.className='tool-note';
    try{render(await api('/inventory-import/preview',{method:'POST',body:{sourceCode,fileName:file.name,mediaType:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',base64:await fileAsBase64(file),defaultOriginatingAgentReference:$('#inventory-import-originating-agent',o).value,defaultResponsibleAgentReference:$('#inventory-import-responsible-agent',o).value}}));}
    catch(error){summary.textContent=`Workbook not accepted: ${error.message}`;summary.className='tool-note error-text';}
  });
  commit.addEventListener('submit',async event=>{event.preventDefault();if(!reviewed?.valid)return toast('Correct and review the workbook before importing');
    const reason=String(new FormData(event.target).get('reason')||'').trim();if(!reason)return;
    try{const result=await api('/inventory-import/commit',{method:'POST',body:{reason,fileName:reviewed.fileName,fileHash:reviewed.fileHash,sourceCode:reviewed.sourceCode,reviewToken:reviewed.reviewToken,rows:reviewed.rows}});
      const created=result.created||result.drafts||[];summary.innerHTML=`<b>Import complete:</b> ${result.importedCount} Draft Inventory record${result.importedCount===1?'':'s'} created; ${result.skippedCount} duplicate${result.skippedCount===1?'':'s'} skipped.<br><b>Generated CORE Inventory IDs:</b> ${created.map(item=>esc(item.inventoryReference)).join(' · ')||'None returned — report this import as failed'}.<br>Review owner/source authority and submit each ready Draft for Manager verification before matching.`;summary.className='tool-note success-text';preview.innerHTML=created.length?`<div class="fee-table-wrap"><table><tr><th>Excel row</th><th>Source record</th><th>CORE Inventory ID</th><th>Next step</th></tr>${created.map(item=>`<tr><td>${Number(item.rowNumber)}</td><td class="mono">${esc(item.externalRecordId)}</td><td><b>${esc(item.inventoryReference)}</b></td><td><button class="btn btn-sm" data-open-imported-inventory="${esc(item.listingId)}">Open Draft</button></td></tr>`).join('')}</table></div>`:'';preview.querySelectorAll('[data-open-imported-inventory]').forEach(button=>button.addEventListener('click',()=>{o.remove();openDetail(button.dataset.openImportedInventory);}));commit.classList.add('hidden');reviewed=null;toast('Reviewed Inventory Drafts created with CORE Inventory IDs');
    }catch(error){summary.textContent=`Import failed: 0 Draft Inventory records created. ${error.message}`;summary.className='tool-note error-text';commit.classList.add('hidden');reviewed=null;}
  });
}

async function loadListings() {
  const requestId = (loadListings.requestId || 0) + 1;
  loadListings.requestId = requestId;
  const p = new URLSearchParams();
  const set = (k, v) => { if (v) p.set(k, v); };
  set('q', $('#f-q').value.trim()); set('areaId', $('#f-area').value); set('community',$('#f-community').value.trim());
  set('propertyType', $('#f-type').value); set('bedrooms', $('#f-beds').value);
  set('minPrice', $('#f-min').value); set('maxPrice', $('#f-max').value);
  set('paymentPlanType', $('#f-plan').value); set('status', $('#f-status').value);
  set('workflowStatus',$('#f-workflow')?.value);
  set('workspaceScope',$('#f-workspace-scope')?.value);
  set('exclusivityTier', $('#f-tier').value); set('developer', $('#f-dev').value.trim());
  set('handoverBefore', $('#f-hb').value); set('handoverAfter', $('#f-ha').value);
  set('sort', $('#f-sort').value);
  const page=loadListings.page||1,pageSize=25;p.set('pageSize',String(pageSize));p.set('page',String(page));
  try {
    const { count, listings } = await api('/listings?' + p.toString());
    if (requestId !== loadListings.requestId) return;
    lastListings = listings;
    const pages=Math.max(1,Math.ceil(count/pageSize)),start=count?(page-1)*pageSize+1:0,end=Math.min(page*pageSize,count);if(page>pages){loadListings.page=pages;return loadListings();}
    $('#f-count').textContent = `${count} matching listing${count === 1 ? '' : 's'} · showing ${start}–${end}`;
    $('#results').innerHTML = listings.length ? `${listings.map(cardHTML).join('')}<div class="filter-actions register-pagination" style="grid-column:1/-1"><button class="btn btn-sm" data-listing-page="previous" ${page<=1?'disabled':''}>Previous</button><span>Page ${page} of ${pages}</span><button class="btn btn-sm" data-listing-page="next" ${page>=pages?'disabled':''}>Next</button></div>`
      : '<div class="empty" style="grid-column:1/-1">No listings match these filters.</div>';
    document.querySelectorAll('.card').forEach(c => c.addEventListener('click', () => openDetail(c.dataset.id)));
    document.querySelectorAll('[data-listing-page]').forEach(button=>button.addEventListener('click',()=>{loadListings.page=page+(button.dataset.listingPage==='next'?1:-1);loadListings();}));
    document.querySelectorAll('[data-update-inventory-availability]').forEach(button=>button.addEventListener('click',event=>{
      event.stopPropagation();
      const listing=listings.find(item=>item.id===button.dataset.updateInventoryAvailability);
      if(listing)openInventoryAvailabilityUpdate(listing);
    }));
  } catch (err) { toast(err.message); }
}

function openInventoryAvailabilityUpdate(listing,{afterSave=loadListings}={}){
  const now=new Date(),current=listing.availabilityConfirmedAt?new Date(listing.availabilityConfirmedAt):now;
  const localValue=new Date(current.getTime()-current.getTimezoneOffset()*60000).toISOString().slice(0,16);
  const expiry=listing.availabilityExpiresAt?new Date(listing.availabilityExpiresAt):null,expiryValue=expiry&&!Number.isNaN(expiry.valueOf())?new Date(expiry.getTime()-expiry.getTimezoneOffset()*60000).toISOString().slice(0,16):'';
  const dialog=overlay(`<div class="modal inventory-availability-quick-modal"><button class="close-x">×</button><div class="eyebrow">QUICK INVENTORY UPDATE</div><h2>Availability effective period</h2><p><b>${esc(listing.inventoryReference||'Inventory')}</b> · ${esc(listing.inventoryHeadline||listing.project)}</p><section class="inventory-availability-current"><span>Current record</span><b>${listing.availabilityConfirmedAt?`Effective ${fmtDate(listing.availabilityConfirmedAt)}`:'No availability confirmation recorded'} · ${listing.availabilityExpiresAt?`expires ${fmtDate(listing.availabilityExpiresAt)}`:'expiry not recorded'}</b></section><form id="inventory-availability-quick-form" class="form-grid"><div class="span3"><label>Availability confirmed with owner or source at *</label><div class="inventory-availability-date-row"><input name="availabilityConfirmedAt" type="datetime-local" required value="${esc(localValue)}"><button class="btn btn-sm" type="button" data-availability-now>Use current date and time</button></div><small>The factual effective time of the latest confirmation.</small></div><div class="span3"><label>Confirmation valid until *</label><input name="availabilityExpiresAt" type="datetime-local" required value="${esc(expiryValue)}"><small>Set the explicit time after which this confirmation must be refreshed. CORE does not invent a seven-day expiry.</small></div><div class="span3 modal-actions"><button class="btn" type="button" data-availability-cancel>Cancel</button><button class="btn btn-primary">Save effective period</button></div></form></div>`),form=$('#inventory-availability-quick-form',dialog);
  $('[data-availability-now]',dialog).addEventListener('click',()=>{const date=new Date();form.elements.availabilityConfirmedAt.value=new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,16);});
  $('[data-availability-cancel]',dialog).addEventListener('click',()=>dialog.remove());
  form.addEventListener('submit',async event=>{event.preventDefault();const button=form.querySelector('button[type="submit"],button.btn-primary');button.disabled=true;try{const effective=form.elements.availabilityConfirmedAt.value,expires=form.elements.availabilityExpiresAt.value;await api(`/listings/${listing.id}/availability`,{method:'PATCH',body:{availabilityConfirmedAt:new Date(effective).toISOString(),availabilityExpiresAt:new Date(expires).toISOString()}});toast('Inventory availability effective period updated');dialog.remove();afterSave();}catch(error){toast(error.message,7000);button.disabled=false;}});
}

function cardHTML(l) {
  const reservationSummary=l.status==='Reserved'&&l.activeBookingReference
    ?`<div class="proposal-readiness blocked"><b>Blocked by ${esc(l.activeBookingReference)}</b><span>Opportunity ${esc(l.activeBookingOpportunityReference)} · until ${fmtDate(l.activeBookingExpiresAt)}</span></div>`:'';
  return `
    <div class="card" data-id="${esc(l.id)}">
    ${l.discountPercent > 0 ? `<div class="discount-tag">−${l.discountPercent}% vs ref</div>` : ''}
    <div class="eyebrow">${esc(l.inventoryReference||'CORE Inventory ID missing')}</div>
    <h3>${esc(l.inventoryHeadline||l.project)}</h3>
    <div class="meta">${esc(l.area)}${l.community?' · '+esc(l.community):''}${l.developer ? ' · ' + esc(l.developer) : ''}</div>
    <div class="price">${fmtPrice(l.price, l.currency)}${l.referencePrice ? ` <small>ref ${fmtPrice(l.referencePrice, l.currency)}</small>` : ''}</div>
    <div class="specs">
      <span>${esc(l.propertyType)}${l.propertyType==='Bulk deal'?` · ${Number(l.bulkUnitCount||0)} properties`:''}</span>
      ${l.bedrooms ? `<span>${esc(l.bedrooms)} BR</span>` : ''}
      ${l.sizeSqft ? `<span>${Number(l.sizeSqft).toLocaleString()} sqft</span>` : ''}
      <span>${esc(handoverLabel(l))}</span>
    </div>
    <div class="badges">
      <span class="badge status-${esc(l.status.replace(' ', '.'))}">${esc(l.status)}${l.closedReason ? ' · ' + esc(l.closedReason) : ''}</span>
      <span class="badge tier">${esc(l.exclusivityTier)}</span>
      <span class="badge">${esc(LISTING_WORKFLOW_LABELS[l.workflowStatus]||l.workflowStatus||'Approved')}</span>
      ${l.paymentPlanType ? `<span class="badge">${esc(l.paymentPlanType)}</span>` : ''}
    </div>
    <div class="inventory-availability-window"><small>${l.availabilityConfirmedAt?`Availability effective ${fmtDate(l.availabilityConfirmedAt)}`:'Availability effective date not recorded'} · ${l.availabilityExpiresAt?`expires ${fmtDate(l.availabilityExpiresAt)}`:'expiry not recorded'}</small></div>
    ${reservationSummary}
    <div class="inventory-availability-card-row"><div><span>Availability effective period</span><b>${l.availabilityConfirmedAt?fmtDate(l.availabilityConfirmedAt):'Not recorded'}</b><small>${l.availabilityExpiresAt?`Expires ${fmtDate(l.availabilityExpiresAt)}`:'Explicit expiry not recorded'}</small></div>${canEditListing(l)?`<button class="btn btn-sm" type="button" data-update-inventory-availability="${esc(l.id)}">Update availability</button>`:''}</div>
    <div class="comment-ct"><span>${l.commentCount || 0} comments</span><span>Listed by ${esc(l.postedByName)}</span><b>View details →</b></div>
  </div>`;
}

/* ============ DETAIL + COMMENTS ============ */
const recordWorkspaceStack=[];
let pendingRecordWorkspace=null;
const RECORD_WORKSPACE_TABS={inventory:'listings',customer:'customers',lead:'crm',opportunity:'opportunities'};
function recordWorkspaceUrl(type,id){const url=new URL(window.location.href);url.searchParams.set('workspace',type);url.searchParams.set('record',id);return url;}
function restoreRecordBackground(state){if(!state||state.restored)return;state.restored=true;for(const page of document.querySelectorAll('[data-opportunity-stage-owner]'))if(page.dataset.opportunityStageOwner===String(state.id))page.remove();document.body.classList.remove('opportunity-stage-open');state.host.parentNode?.removeChild(state.host);const view=$('#view');view.append(state.previous);recordWorkspaceStack.pop();const main=document.querySelector('main');if(main)main.scrollTop=state.scrollTop;}
function leaveRecordWorkspace(state,{fromHistory=false,discard=false}={}){
  if(!state||state.restored)return;
  if(state.dirty&&!discard){
    const dialog=overlay(`<div class="modal confirmation-modal"><button class="close-x">×</button><h2>Unsaved changes</h2><p>This workspace will remain open unless you explicitly save or discard the current section.</p><div class="modal-actions"><button class="btn" data-continue-editing>Continue editing</button>${state.lastForm?'<button class="btn btn-primary" data-save-current>Save current section</button>':''}<button class="btn btn-danger" data-discard-workspace>Discard unsaved changes and leave</button></div></div>`);
    $('[data-continue-editing]',dialog)?.addEventListener('click',()=>dialog.remove());
    $('[data-save-current]',dialog)?.addEventListener('click',()=>{dialog.remove();state.lastForm?.requestSubmit();});
    $('[data-discard-workspace]',dialog)?.addEventListener('click',()=>{dialog.remove();state.dirty=false;state.lastForm=null;leaveRecordWorkspace(state,{fromHistory,discard:true});});return;
  }
  if(!fromHistory&&state.pushed){history.back();return;}
  restoreRecordBackground(state);
  if(!fromHistory){const url=new URL(window.location.href);url.searchParams.delete('workspace');url.searchParams.delete('record');history.replaceState({tab:state.returnTab},'',url);}
}
function recordWorkspace(html,{type,id,returnTab=RECORD_WORKSPACE_TABS[type]||currentTab}={}){
  const view=$('#view'),previous=document.createDocumentFragment(),main=document.querySelector('main'),scrollTop=main?.scrollTop||0;
  while(view.firstChild)previous.append(view.firstChild);
  const host=document.createElement('section');host.className='record-workspace';host.dataset.workspaceType=type;host.dataset.workspaceRecord=id;host.innerHTML=html;view.append(host);if(main)main.scrollTop=0;
  const surface=host.querySelector('.modal')||host.firstElementChild;surface?.classList.add('record-workspace-surface');
  const state={host,previous,scrollTop,type,id,returnTab,dirty:false,lastForm:null,restored:false,pushed:false};recordWorkspaceStack.push(state);
  host.addEventListener('input',event=>{const form=event.target.closest('form');if(form){state.dirty=true;state.lastForm=form;}});
  host.addEventListener('change',event=>{const form=event.target.closest('form');if(form){state.dirty=true;state.lastForm=form;}});
  const close=host.querySelector('.close-x');if(close){close.innerHTML='<span aria-hidden="true">←</span><span class="close-label">Back</span>';close.setAttribute('aria-label',`Back to ${returnTab}`);close.addEventListener('click',event=>{event.preventDefault();event.stopImmediatePropagation();leaveRecordWorkspace(state);},{capture:true});}
  const current=new URL(window.location.href),same=current.searchParams.get('workspace')===type&&current.searchParams.get('record')===String(id),url=recordWorkspaceUrl(type,id);
  state.pushed=!same;
  history[same?'replaceState':'pushState']({workspace:type,record:String(id),returnTab},'',url);
  host.remove=()=>restoreRecordBackground(state);
  return host;
}
function openRecordRouteFromLocation(){const url=new URL(window.location.href),type=url.searchParams.get('workspace'),id=url.searchParams.get('record');if(!ME||!type||!id)return;const tab=RECORD_WORKSPACE_TABS[type];if(tab&&currentTab!==tab)switchTab(tab);setTimeout(()=>type==='inventory'?(id==='new'?openListingForm():openDetail(id)):type==='customer'?(id==='new'?openNewCustomerForm():openCustomer(id)):type==='lead'?(id==='new'?openNewLeadForm():id.startsWith('new:')?openNewLeadForm(id.slice(4)):openLead(id)):type==='opportunity'?(id.startsWith('new:')?openLead(id.slice(4)):openOpportunityDetail(id)):null,0);}
window.addEventListener('popstate',()=>{const state=recordWorkspaceStack.at(-1);if(state?.dirty){history.pushState({workspace:state.type,record:String(state.id),returnTab:state.returnTab},'',recordWorkspaceUrl(state.type,state.id));leaveRecordWorkspace(state);return;}if(state){leaveRecordWorkspace(state,{fromHistory:true,discard:true});const url=new URL(window.location.href);if(url.searchParams.get('workspace'))openRecordRouteFromLocation();return;}openRecordRouteFromLocation();});
function overlay(html) {
  if(pendingRecordWorkspace){
    const options=pendingRecordWorkspace,expected=options.type==='opportunity'?(String(options.id).startsWith('new:')?'LEAD CONVERSION':'opportunity-modal'):{inventory:'listing-'}[options.type];
    pendingRecordWorkspace=null;
    if(!expected||html.includes(expected))return recordWorkspace(html,options);
  }
  const o = document.createElement('div');
  o.className = 'overlay'; o.innerHTML = html;
  const closeButton=o.querySelector('.close-x');
  if(closeButton&&!closeButton.querySelector('.close-label'))closeButton.innerHTML='<span aria-hidden="true">×</span><span class="close-label">Close</span>';
  closeButton?.setAttribute('aria-label','Close workspace');
  // A background click is too easy to trigger while scrolling or selecting in
  // long business forms. Read-only dialogs may still use the backdrop; forms
  // close only through their explicit close/cancel control.
  o.addEventListener('click', (e) => { if (e.target === o&&!o.querySelector('form')) o.remove(); });
  closeButton?.addEventListener('click', () => o.remove());
  document.body.appendChild(o);
  installBusinessAmountInputs(o);
  return o;
}

