let listingMappingState={versions:[],entries:[],fields:[]};
function refreshListingMappingCoreOptions(){const field=listingMappingState.fields.find(item=>item.code===$('#listing-mapping-field')?.value),select=$('#listing-mapping-core');if(select)select.innerHTML=(field?.options||[]).map(option=>`<option value="${esc(option.value)}">${esc(option.label)} · ${esc(option.value)}</option>`).join('');}
async function createListingMappingVersion(e){e.preventDefault();const body=Object.fromEntries(new FormData(e.target));body.cloneFromId=body.cloneFromId||null;try{await api('/admin/listing-mappings',{method:'POST',body});toast('Draft provider mapping version created');e.target.reset();await loadListingMappings();}catch(err){toast(err.message,7000);}}
async function addListingMappingEntry(e){e.preventDefault();const body=Object.fromEntries(new FormData(e.target)),versionId=body.versionId;delete body.versionId;try{await api(`/admin/listing-mappings/${versionId}/entries`,{method:'POST',body});toast('External value mapped to governed CORE value');e.target.elements.externalValue.value='';await loadListingMappings();}catch(err){toast(err.message,7000);}}
async function mappingLifecycle(version,action){const reason=prompt(`Reason to ${action} ${version.providerCode} ${version.versionCode}`);if(!reason)return;let evidence=null;if(action!=='retire'){evidence=prompt(action==='test'?'Test evidence (sample event or result reference)':'Approval evidence or decision reference');if(!evidence)return;}try{await api(`/admin/listing-mappings/${version.id}/${action}`,{method:'POST',body:{reason,evidence}});toast(`Mapping version ${action==='test'?'tested':action+'d'}`);await loadListingMappings();}catch(err){toast(err.message,7000);}}
async function loadListingMappings(){const table=$('#listing-mapping-table');if(!table)return;try{listingMappingState=await api('/admin/listing-mappings');const{versions,entries,fields}=listingMappingState,drafts=versions.filter(version=>version.status==='draft');$('#listing-mapping-clone').innerHTML='<option value="">Start empty</option>'+versions.map(version=>`<option value="${version.id}">${esc(version.providerCode)} · ${esc(version.versionCode)} · ${esc(version.status)}</option>`).join('');$('#listing-mapping-draft').innerHTML=drafts.length?drafts.map(version=>`<option value="${version.id}">${esc(version.providerCode)} · ${esc(version.versionCode)}</option>`).join(''):'<option value="">Create a Draft version first</option>';$('#listing-mapping-field').innerHTML=fields.map(field=>`<option value="${field.code}">${esc(field.label)}</option>`).join('');refreshListingMappingCoreOptions();table.innerHTML=versions.length?versions.map(version=>{const rows=entries.filter(entry=>entry.versionId===version.id),next={draft:'test',tested:'approve',approved:'activate',active:'retire'}[version.status];return`<article class="mapping-version-card"><header><div><b>${esc(version.providerCode)} · ${esc(version.versionCode)}</b><small>${esc(version.name)} · ${version.mappingCount} mappings</small></div><span class="badge">${esc(version.status)}</span></header><p>${esc(version.description||'No description recorded')}</p>${rows.length?`<table><tr><th>CORE field</th><th>External value</th><th>CORE value</th><th></th></tr>${rows.map(entry=>`<tr><td>${esc(fields.find(field=>field.code===entry.fieldCode)?.label||entry.fieldCode)}</td><td>${esc(entry.externalValue)}</td><td>${esc(entry.coreValue)}</td><td>${version.status==='draft'?`<button class="btn btn-sm" data-delete-mapping="${entry.id}" data-version="${version.id}">Remove</button>`:''}</td></tr>`).join('')}</table>`:'<p class="tool-note">No value mappings in this version.</p>'}<footer><small>Created by ${esc(version.createdByName)} ${fmtDate(version.createdAt)}${version.lifecycleReason?` · ${esc(version.lifecycleReason)}`:''}</small>${next?`<button class="btn ${next==='activate'?'btn-primary':''} btn-sm" data-mapping-action="${next}" data-version="${version.id}">${next[0].toUpperCase()+next.slice(1)}</button>`:''}</footer></article>`;}).join(''):'<div class="empty compact">No governed provider mapping versions yet.</div>';table.querySelectorAll('[data-mapping-action]').forEach(button=>button.onclick=()=>mappingLifecycle(versions.find(version=>version.id===button.dataset.version),button.dataset.mappingAction));table.querySelectorAll('[data-delete-mapping]').forEach(button=>button.onclick=async()=>{if(!confirm('Remove this Draft mapping entry?'))return;try{await api(`/admin/listing-mappings/${button.dataset.version}/entries/${button.dataset.deleteMapping}`,{method:'DELETE'});await loadListingMappings();}catch(err){toast(err.message);}});}catch(err){table.textContent=err.message;}}

async function loadPropertyMediaApprovalPolicy(){const form=$('#media-policy-form'),status=$('#media-policy-status');if(!form||!status)return;try{const{policy}=await api('/admin/property-media-approval-policy');form.elements.managerApprovalRequired.value=policy.managerApprovalRequired?'true':'false';status.innerHTML=`Current policy: <b>${policy.managerApprovalRequired?'Responsible Manager approval is required':'Compliant uploads are approved immediately'}</b><br>Last reason: ${esc(policy.changeReason)} · Updated ${fmtDate(policy.updatedAt)}`;}catch(err){status.textContent=err.message;}}
async function savePropertyMediaApprovalPolicy(e){e.preventDefault();const form=e.target,managerApprovalRequired=form.elements.managerApprovalRequired.value==='true',reason=form.elements.reason.value.trim();if(!reason)return toast('Enter the reason for changing or confirming this policy');try{await api('/admin/property-media-approval-policy',{method:'PATCH',body:{managerApprovalRequired,reason}});toast(managerApprovalRequired?'Manager approval retained for future media uploads':'Media approval made optional; future compliant uploads will be approved immediately');form.elements.reason.value='';await loadPropertyMediaApprovalPolicy();}catch(err){toast(err.message,7000);}}
async function loadListingApprovalPolicy(){const form=$('#listing-policy-form'),status=$('#listing-policy-status');if(!form||!status)return;try{const{policy}=await api('/admin/listing-approval-policy');form.elements.managerApprovalRequired.value=policy.managerApprovalRequired?'true':'false';status.innerHTML=`Current policy: <b>${policy.managerApprovalRequired?'Responsible Manager approval is required':'Publication-ready submissions are approved immediately'}</b><br>Last reason: ${esc(policy.changeReason)} · Updated ${fmtDate(policy.updatedAt)}`;}catch(err){status.textContent=err.message;}}
async function saveListingApprovalPolicy(e){e.preventDefault();const form=e.target,managerApprovalRequired=form.elements.managerApprovalRequired.value==='true',reason=form.elements.reason.value.trim();if(!reason)return toast('Enter the reason for changing or confirming this policy');try{await api('/admin/listing-approval-policy',{method:'PATCH',body:{managerApprovalRequired,reason}});toast(managerApprovalRequired?'Manager approval retained for future listing submissions':'Listing approval made optional; future publication-ready submissions will be approved immediately');form.elements.reason.value='';await loadListingApprovalPolicy();}catch(err){toast(err.message,7000);}}

const minutesFromTime=value=>{const[h,m]=String(value).split(':').map(Number);return h*60+m;},timeFromMinutes=value=>`${String(Math.floor(Number(value)/60)%24).padStart(2,'0')}:${String(Number(value)%60).padStart(2,'0')}`;
async function createSlaPolicy(e){e.preventDefault();const b=Object.fromEntries(new FormData(e.target));b.workDays=Array.from(e.target.elements.workDays.selectedOptions).map(x=>Number(x.value));b.workStartMinute=minutesFromTime(b.workStartTime);b.workEndMinute=minutesFromTime(b.workEndTime);for(const k of ['acceptanceMinutes','firstContactMinutes','qualificationHotElapsedMinutes','qualificationWarmBusinessMinutes','qualificationColdBusinessDays','qualificationColdNurtureBusinessDays'])b[k]=Number(b[k]);delete b.workStartTime;delete b.workEndTime;try{await api('/admin/sla-policies',{method:'POST',body:b});toast('SLA policy draft created');loadSlaPolicies();}catch(err){toast(err.message);}}
async function loadSlaPolicies(){try{const{policies}=await api('/admin/sla-policies'),days=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];$('#sla-table').innerHTML=`<table><tr><th>Policy</th><th>Business hours</th><th>Lead response</th><th>Qualification follow-up</th><th>Status</th><th>Actions</th></tr>${policies.map(p=>`<tr><td>${esc(p.name)}</td><td>${timeFromMinutes(p.workStartMinute)}–${timeFromMinutes(p.workEndMinute)}<small>${(p.workDays||[]).map(x=>days[x]).join(', ')}</small></td><td>Acceptance: ${p.acceptanceMinutes} business min<small>First contact: ${p.firstContactMinutes} business min</small></td><td>Hot: ${p.qualificationHotElapsedMinutes??15} elapsed min (24/7)<small>Warm: ${p.qualificationWarmBusinessMinutes??240} business min · Cold: ${p.qualificationColdBusinessDays??1} business day, then every ${p.qualificationColdNurtureBusinessDays??5} business days</small></td><td>${esc(p.status)}</td><td>${p.status==='draft'?`<button class="btn btn-primary btn-sm" data-activate-sla="${p.id}">Activate</button>`:''}</td></tr>`).join('')}</table>`;document.querySelectorAll('[data-activate-sla]').forEach(b=>b.addEventListener('click',async()=>{try{await api(`/admin/sla-policies/${b.dataset.activateSla}/activate`,{method:'POST'});loadSlaPolicies();}catch(err){toast(err.message);}}));}catch(err){$('#sla-table').textContent=err.message;}}
function clearAreaForm(){const form=$('#area-form');form.reset();form.elements.id.value='';form.elements.stableCode.disabled=false;form.elements.displayOrder.value=100;$('#area-save').textContent='Add area';$('#area-cancel').classList.add('hidden');}
function editArea(area){const form=$('#area-form');form.elements.id.value=area.id;form.elements.stableCode.value=area.stableCode;form.elements.stableCode.disabled=true;form.elements.businessLabel.value=area.businessLabel;form.elements.emirate.value=area.emirate;form.elements.displayOrder.value=area.displayOrder;$('#area-save').textContent='Save area changes';$('#area-cancel').classList.remove('hidden');form.scrollIntoView({behavior:'smooth',block:'center'});}
async function saveArea(e){e.preventDefault();const form=e.target,b=Object.fromEntries(new FormData(form)),id=b.id;delete b.id;b.displayOrder=Number(b.displayOrder);if(id){const reason=prompt('Reason for changing this maintained area');if(!reason)return;b.reason=reason;}try{await api(id?`/admin/areas/${id}`:'/admin/areas',{method:id?'PATCH':'POST',body:b});listingAreas=null;toast(id?'Area updated':'Area added');clearAreaForm();await loadAreas();await loadRoutingRules();}catch(err){toast(err.message);}}
let areaImportPreview=null;
function renderAreaImportPreview(result){areaImportPreview=result;const invalid=result.rows.filter(row=>row.errors.length),skipped=result.rows.filter(row=>row.skipped),ready=result.rows.filter(row=>!row.errors.length&&!row.skipped),feedback=$('#area-import-feedback'),confirm=$('#area-import-confirm');feedback.textContent=invalid.length?`${invalid.length} of ${result.rowCount} rows contain conflicts or invalid data. Nothing has been imported.`:`${ready.length} new area${ready.length===1?' is':'s are'} ready to import; ${skipped.length} existing or repeated row${skipped.length===1?' was':'s were'} skipped automatically.`;feedback.className=`tool-note ${invalid.length?'error-text':'success-text'}`;confirm.classList.toggle('hidden',invalid.length>0||ready.length===0);$('#area-import-preview-table').innerHTML=`<div class="fee-table-wrap"><table class="area-import-preview-table"><tr><th>Excel row</th><th>Customer-facing area</th><th>Emirate</th><th>Order</th><th>Validation</th></tr>${result.rows.map(row=>`<tr class="${row.errors.length?'import-row-error':row.skipped?'import-row-skipped':'import-row-valid'}"><td>${row.rowNumber}</td><td>${esc(row.businessLabel||'—')}</td><td>${esc(row.emirate||'—')}</td><td>${row.displayOrder??'—'}</td><td>${row.errors.length?esc(row.errors.join(' · ')):row.skipped?esc(row.skipReason):'Ready to import'}</td></tr>`).join('')}</table></div>`;}
async function reviewAreaImport(){const input=$('#area-import-file'),file=input.files[0];areaImportPreview=null;$('#area-import-confirm').classList.add('hidden');$('#area-import-preview-table').innerHTML='';if(!file)return toast('Choose the completed Area Excel template first');if(!file.name.toLowerCase().endsWith('.xlsx'))return toast('Choose an .xlsx workbook created from the approved Area template');if(file.size<1||file.size>2097152)return toast('Area workbook must be between 1 byte and 2 MB');$('#area-import-feedback').textContent='Reviewing workbook…';try{const result=await api('/admin/areas/import/preview',{method:'POST',body:{fileName:file.name,mediaType:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',base64:await fileAsBase64(file)}});renderAreaImportPreview(result);}catch(err){$('#area-import-feedback').textContent=`Workbook not accepted: ${err.message}`;$('#area-import-feedback').className='tool-note error-text';}}
async function commitAreaImport(){if(!areaImportPreview?.valid)return toast('Resolve genuine conflicts before importing');const reason=prompt('Reason for importing these maintained areas','Initial governed area setup');if(!reason)return;try{const result=await api('/admin/areas/import/commit',{method:'POST',body:{reason,rows:areaImportPreview.rows}});listingAreas=null;toast(`${result.importedCount} maintained areas imported; ${result.skippedCount||0} duplicates skipped`);areaImportPreview=null;$('#area-import-file').value='';$('#area-import-feedback').textContent=`Import completed: ${result.importedCount} areas created and ${result.skippedCount||0} existing or repeated rows skipped.`;$('#area-import-feedback').className='tool-note success-text';$('#area-import-preview-table').innerHTML='';$('#area-import-confirm').classList.add('hidden');await loadAreas();await loadRoutingRules();}catch(err){toast(`Areas not imported: ${err.message}`,8000);$('#area-import-feedback').textContent='The import was not committed. Review the workbook again before retrying.';$('#area-import-feedback').className='tool-note error-text';$('#area-import-confirm').classList.add('hidden');}}
async function loadAreas(){try{const{areas}=await api('/admin/areas');$('#area-table').innerHTML=areas.length?`<table><tr><th>Order</th><th>Area</th><th>Emirate</th><th>Status</th><th>Actions</th></tr>${areas.map(a=>`<tr><td>${a.displayOrder}</td><td><span class="area-name">${esc(a.businessLabel)}</span></td><td>${esc(a.emirate)}</td><td><span class="pill">${a.active?'Active':'Retired'}</span></td><td><button class="btn btn-sm" data-edit-area="${a.id}" ${a.active?'':'disabled'}>Edit</button> <button class="btn btn-sm" data-toggle-area="${a.id}" data-active="${a.active?0:1}">${a.active?'Retire':'Reactivate'}</button></td></tr>`).join('')}</table>`:'<div class="empty compact">No maintained areas yet. Add the areas used for customer requirements and routing.</div>';$('#area-table').querySelectorAll('[data-edit-area]').forEach(button=>button.addEventListener('click',()=>editArea(areas.find(a=>a.id===button.dataset.editArea))));$('#area-table').querySelectorAll('[data-toggle-area]').forEach(button=>button.addEventListener('click',async()=>{const active=button.dataset.active==='1',reason=prompt(`Reason for ${active?'reactivating':'retiring'} this area`);if(!reason)return;try{await api(`/admin/areas/${button.dataset.toggleArea}`,{method:'PATCH',body:{active,reason}});listingAreas=null;toast(active?'Area reactivated':'Area retired');clearAreaForm();await loadAreas();await loadRoutingRules();}catch(err){toast(err.message);}}));}catch(err){$('#area-table').textContent=err.message;}}
function clearRoutingForm(){const form=$('#routing-form');form.reset();form.elements.id.value='';form.elements.priority.value=100;$('#routing-save').textContent='Add rule';$('#routing-cancel').classList.add('hidden');}
function editRoutingRule(rule){const form=$('#routing-form');form.elements.id.value=rule.id;form.elements.name.value=rule.name;form.elements.priority.value=rule.priority;form.elements.source.value=rule.source||'';form.elements.businessType.value=rule.businessType||'';form.elements.areaId.value=rule.areaId||'';form.elements.teamId.value=rule.teamId||'';$('#routing-save').textContent='Save rule changes';$('#routing-cancel').classList.remove('hidden');form.scrollIntoView({behavior:'smooth',block:'center'});}
async function createRoutingRule(e){e.preventDefault();const b=Object.fromEntries(new FormData(e.target)),id=b.id;delete b.id;b.priority=Number(b.priority);b.source=b.source||null;b.businessType=b.businessType||null;if(!b.teamId&&(b.source||b.businessType)&&!confirm('No destination team queue is selected. Save this matching rule to the Company Unassigned Queue?'))return;if(id){const reason=prompt('Reason for changing this routing rule');if(!reason)return;b.reason=reason;}try{await api(id?`/admin/routing-rules/${id}`:'/admin/routing-rules',{method:id?'PATCH':'POST',body:b});toast(id?'Routing rule updated':'Routing rule added');clearRoutingForm();loadRoutingRules();}catch(err){toast(err.message);}}
async function loadRoutingRules(){try{const[{rules},{teams}]=await Promise.all([api('/admin/routing-rules'),api('/crm/teams')]);$('#routing-team').innerHTML='<option value="">Company Unassigned Queue</option>'+teams.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('');$('#inv-team').innerHTML=$('#add-user-team').innerHTML='<option value="">Not applicable</option>'+teams.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('');$('#routing-table').innerHTML=`<table><tr><th>Priority</th><th>Rule</th><th>Match</th><th>Destination team queue</th><th>Status</th><th>Actions</th></tr>${rules.map(x=>`<tr><td>${x.priority}</td><td>${esc(x.name)}</td><td>${esc(x.source||'Any source')} · ${esc(x.businessType||'Any business')}</td><td>${x.teamName?esc(x.teamName)+' · unassigned queue':'Company Unassigned Queue'}</td><td>${x.active?'Active':'Retired'}</td><td><button class="btn btn-sm" data-edit-routing="${x.id}" ${x.active?'':'disabled'}>Edit</button> <button class="btn btn-sm" data-toggle-routing="${x.id}" data-active="${x.active?0:1}">${x.active?'Retire':'Reactivate'}</button></td></tr>`).join('')}</table>`;$('#routing-table').querySelectorAll('[data-edit-routing]').forEach(button=>button.addEventListener('click',()=>editRoutingRule(rules.find(rule=>rule.id===button.dataset.editRouting))));$('#routing-table').querySelectorAll('[data-toggle-routing]').forEach(button=>button.addEventListener('click',async()=>{const active=button.dataset.active==='1',reason=prompt(`Reason for ${active?'reactivating':'retiring'} this routing rule`);if(!reason)return;try{await api(`/admin/routing-rules/${button.dataset.toggleRouting}`,{method:'PATCH',body:{active,reason}});toast(active?'Routing rule reactivated':'Routing rule retired');clearRoutingForm();loadRoutingRules();}catch(err){toast(err.message);}}));}catch(err){$('#routing-table').textContent=err.message;}}
