  $('#campaign-form',o).addEventListener('submit',async e=>{e.preventDefault();try{const body=Object.fromEntries(new FormData(e.target));await api('/crm/campaigns',{method:'POST',body});toast('Campaign draft created');o.remove();openCampaignMaintenance();}catch(err){toast(err.message,7000);}});
