function addQualificationFactor(f={}){const row=document.createElement('div');row.className='maintenance-row qualification-factor';row.innerHTML=`<input data-field="label" placeholder="Business label" value="${esc(f.label||'')}"><input data-field="description" placeholder="Description" value="${esc(f.description||'')}"><input data-field="code" placeholder="stable_code" pattern="[a-z][a-z0-9_]*" value="${esc(f.code||'')}"><select data-field="inputSource"><option value="agent_confirmed">Agent confirmed</option><option value="system">System field</option></select><input data-field="min" type="number" placeholder="Min" value="${f.min??0}"><input data-field="max" type="number" placeholder="Max" value="${f.max??10}"><input data-field="weight" type="number" placeholder="Weight %" value="${f.weight??0}"><label><input data-field="required" type="checkbox" ${f.required?'checked':''}> Required</label><select data-field="missingTreatment"><option value="reject">Block if missing</option><option value="zero">Score zero</option><option value="exclude">Exclude</option></select><button class="btn btn-sm" type="button">Remove</button>`;row.querySelector('[data-field="inputSource"]').value=f.inputSource||'agent_confirmed';row.querySelector('[data-field="missingTreatment"]').value=f.missingTreatment||'reject';row.querySelector('button').onclick=()=>{row.remove();updateQualificationWeight();};row.querySelectorAll('input').forEach(x=>x.addEventListener('input',updateQualificationWeight));$('#qualification-factors').append(row);updateQualificationWeight();}
function updateQualificationWeight(){const total=Array.from(document.querySelectorAll('.qualification-factor [data-field="weight"]')).reduce((s,x)=>s+Number(x.value||0),0);$('#qualification-weight-total').textContent=`Total weight: ${total}%${total===100?' ✓':' — must equal 100%'}`;}
const collectRows=(selector)=>Array.from(document.querySelectorAll(selector)).map(row=>Object.fromEntries(Array.from(row.querySelectorAll('[data-field]')).map(el=>[el.dataset.field,el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value])));
async function createQualificationModel(e){e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),factors=collectRows('.qualification-factor');try{const body={...f,factors,guidance:{Cold:{strategy:f.coldGuidance},Warm:{strategy:f.warmGuidance},Hot:{strategy:f.hotGuidance}},thresholds:{warmMin:Number(f.warmMin),hotMin:Number(f.hotMin)}};await api('/admin/qualification-models',{method:'POST',body});toast('Lead Qualification draft created');loadQualificationModels();}catch(err){toast(err.message);}}
function openQualificationModelTest(model){const dialog=overlay(`<div class="modal lead-modal"><button class="close-x">×</button><div class="eyebrow">QUALIFICATION VERSION TEST · NO LEAD ASSESSMENT SAVED</div><h2>Test ${esc(model.name)} v${model.version}</h2><p class="tool-note">This uses the same approved answer controls an agent will receive. Review every question, choice, help text, weight and score contribution before approval.</p><form id="qualification-model-test-form"><div class="qualification-question-list">${model.factors.map(f=>`<div class="qualification-question"><label>${esc(f.question||f.label)}${f.required?' *':''}</label>${f.description?`<small>${esc(f.description)}</small>`:''}${qualificationQuestionControl(f)}<small>Weight ${Number(f.weight)}%${f.answerType==='single_select'?' · Select one maintained choice':f.answerType==='yes_no'?' · Select Yes or No':` · Enter ${Number(f.min)} to ${Number(f.max)}`}</small></div>`).join('')}</div><div class="modal-actions"><button class="btn" type="button" data-cancel-model-test>Cancel</button><button class="btn btn-primary">Calculate test result</button></div></form><div data-model-test-result></div></div>`),form=$('#qualification-model-test-form',dialog);dialog.querySelector('[data-cancel-model-test]').addEventListener('click',()=>dialog.remove());form.addEventListener('submit',async event=>{event.preventDefault();const inputs=Object.fromEntries(model.factors.map(f=>[f.code,form.elements[f.code].value]));try{const result=await api(`/admin/qualification-models/${model.id}/test`,{method:'POST',body:{inputs}});dialog.querySelector('[data-model-test-result]').innerHTML=`<div class="qualification-result"><h3>${esc(result.temperature)} · score ${Number(result.score).toFixed(2)}</h3>${result.contributions.map(x=>`<div><b>${esc(x.label)}</b><span>Answer ${x.value??'missing'} · weight ${Number(x.weight)}% · contribution ${Number(x.contribution||0).toFixed(2)}</span></div>`).join('')}</div>`;toast('Questionnaire test calculated; no Lead assessment was saved');}catch(error){toast(error.message,8000);}});}
function bindQualificationRetirementActions(table){table.querySelectorAll('[data-retire-model]').forEach(button=>button.addEventListener('click',()=>globalThis.retireQualificationModel(button.dataset.retireModel)));}
async function loadQualificationModels(){try{const{models}=await api('/admin/qualification-models'),objectives=[['buy','Buy'],['sell','Sell'],['rent','Rent'],['rent_out','Rent out']],activeObjectives=new Set(models.filter(x=>x.status==='active').map(x=>x.customerObjective)),table=$('#qualification-model-table');table.innerHTML=`<div class="qualification-coverage"><b>Active questionnaire coverage</b>${objectives.map(([value,label])=>`<span class="${activeObjectives.has(value)?'coverage-active':'coverage-missing'}">${label}: ${activeObjectives.has(value)?'Active':'No active version'}</span>`).join('')}</div>${models.length?`<table><tr><th>Lead Qualification Version</th><th>Customer objective</th><th>Questions / weight</th><th>Score bands</th><th>Status</th><th>Next action</th></tr>${models.map(m=>`<tr><td>${esc(m.name)} v${m.version}<small>${esc(m.modelCode)} · ${esc(m.purpose)}</small></td><td>${esc(Object.fromEntries(objectives)[m.customerObjective]||'Legacy / review required')}</td><td>${m.factors.length} questions · ${m.factors.reduce((s,x)=>s+Number(x.weight),0)}%</td><td>Cold below ${m.thresholds.warmMin}<br>Warm ${m.thresholds.warmMin}–${m.thresholds.hotMin-0.01}<br>Hot ${m.thresholds.hotMin}+</td><td>${esc(m.status)}</td><td><button class="btn btn-sm" data-test-model="${m.id}">Test questionnaire</button>${m.status==='draft'?` <button class="btn btn-sm" data-approve-model="${m.id}">Approve tested draft</button>`:''}${m.status==='approved'?` <button class="btn btn-primary btn-sm" data-activate-model="${m.id}">Activate for leads</button>`:''}${m.status==='active'?'<small>Available from Assess qualification</small>':''}${m.status!=='retired'?` <button class="btn btn-sm" type="button" data-retire-model="${m.id}">Retire version</button>`:''}</td></tr>`).join('')}</table>`:'<p class="empty-state">No Lead Qualification Versions yet. Create a draft, test it, approve it and activate it before assessing a lead.</p>'}`;table.querySelectorAll('[data-test-model]').forEach(button=>button.addEventListener('click',()=>openQualificationModelTest(models.find(model=>model.id===button.dataset.testModel))));table.querySelectorAll('[data-approve-model]').forEach(b=>b.addEventListener('click',async()=>{const reason=prompt('Approval reason (confirm that the questionnaire and test result were reviewed)');if(!reason)return;try{await api(`/admin/qualification-models/${b.dataset.approveModel}/approve`,{method:'POST',body:{reason}});toast('Version approved; activate it to make it available on leads');loadQualificationModels();}catch(err){toast(err.message);}}));table.querySelectorAll('[data-activate-model]').forEach(b=>b.addEventListener('click',async()=>{if(!confirm('Activate this version for the exact Customer objective? The previous active version of the same model and objective will be retired.'))return;try{await api(`/admin/qualification-models/${b.dataset.activateModel}/activate`,{method:'POST'});toast('Lead Qualification Version activated for the exact Customer objective');loadQualificationModels();}catch(err){toast(err.message);}}));bindQualificationRetirementActions(table);}catch(err){$('#qualification-model-table').textContent=err.message;}}
function addFeeBand(container,b={}){const row=document.createElement('div');row.className='maintenance-row fee-band';row.innerHTML=`<div><label>Condition field</label><select data-band-field="dimension"><option value="purchase_price">Purchase price</option><option value="mortgage_amount">Mortgage amount</option><option value="property_value">Property value</option><option value="property_type">Property type</option><option value="service_channel">Service channel</option></select></div><div><label>Comparison</label><select data-band-field="operator"><option value="below">Below</option><option value="at_or_above">At or above</option><option value="equals">Equals</option></select></div><div><label>Condition value</label><input data-band-field="value" value="${esc(b.value??'')}" placeholder="500000 or apartment,office"></div><div><label>Charge amount</label><input data-band-field="amount" type="number" min="0" step="0.01" value="${b.amount??''}"></div><button class="btn btn-sm" type="button">Remove band</button>`;row.querySelector('[data-band-field="dimension"]').value=b.dimension||'purchase_price';row.querySelector('[data-band-field="operator"]').value=b.operator||'below';row.querySelector('button').onclick=()=>row.remove();container.append(row);}
function refreshFeeItem(row){const type=row.querySelector('[data-field="calculationType"]').value;row.querySelectorAll('[data-formula]').forEach(x=>x.classList.toggle('hidden',!x.dataset.formula.split(' ').includes(type)));const bands=row.querySelector('.fee-bands');if(type==='conditional_fixed'&&!bands.children.length)addFeeBand(bands);}
function addFeeItem(f={}){const row=document.createElement('div');row.className='fee-rule-card fee-item';row.innerHTML=`<div class="fee-rule-head"><b>Fee rule</b><button class="btn btn-sm" type="button" data-remove-fee>Remove rule</button></div><div class="form-grid fee-rule-grid"><div><label>Business label *</label><input data-field="label" value="${esc(f.label||'')}" placeholder="DLD transfer fee"></div><div><label>Stable code *</label><input data-field="code" pattern="[a-z][a-z0-9_]*" value="${esc(f.code||'')}" placeholder="dld_transfer_fee"></div><div><label>Calculation formula *</label><select data-field="calculationType"><option value="percentage">Percentage</option><option value="fixed">Fixed amount</option><option value="conditional_fixed">Conditional fixed amount</option><option value="percentage_plus_fixed">Percentage plus fixed amount</option><option value="quantity">Amount per unit/drawing</option><option value="estimate_range">Estimated range</option></select></div><div><label>Calculated on *</label><select data-field="calculationBasis"><option value="purchase_price">Purchase price</option><option value="mortgage_amount">Mortgage/loan amount</option><option value="property_value">Property valuation</option><option value="quantity">Quantity</option><option value="none">No amount; fixed rule</option></select></div><div data-formula="percentage percentage_plus_fixed"><label>Percentage rate</label><input data-field="ratePercent" type="number" min="0" step="0.0001" value="${f.ratePercent??''}"></div><div data-formula="fixed"><label>Fixed amount</label><input data-field="amount" type="number" min="0" step="0.01" value="${f.amount??''}"></div><div data-formula="percentage_plus_fixed"><label>Additional fixed amount</label><input data-field="fixedAddition" type="number" min="0" step="0.01" value="${f.fixedAddition??''}"></div><div data-formula="percentage percentage_plus_fixed"><label>Maximum/cap (optional)</label><input data-field="capAmount" type="number" min="0" step="0.01" value="${f.capAmount??''}"></div><div data-formula="quantity"><label>Amount per unit/drawing</label><input data-field="unitAmount" type="number" min="0" step="0.01" value="${f.unitAmount??''}"></div><div data-formula="quantity"><label>Quantity input code</label><input data-field="quantityCode" value="${esc(f.quantityCode||'quantity')}" placeholder="drawings"></div><div data-formula="estimate_range"><label>Minimum estimate</label><input data-field="minAmount" type="number" min="0" step="0.01" value="${f.minAmount??''}"></div><div data-formula="estimate_range"><label>Maximum estimate</label><input data-field="maxAmount" type="number" min="0" step="0.01" value="${f.maxAmount??''}"></div><div><label>VAT added to this charge (%)</label><input data-field="vatPercent" type="number" min="0" max="100" step="0.01" value="${f.vatPercent??0}"></div><div><label>Transaction applicability</label><select data-field="transactionType"><option value="all">All transactions</option><option value="purchase">Any purchase</option><option value="resale">Resale purchase</option><option value="off_plan">Off-plan purchase</option><option value="mortgage">Mortgage</option><option value="investment">Investment analysis</option><option value="gift">Gift</option></select></div><div><label>Funding method applicability</label><select data-field="fundingMethod"><option value="all">All funding methods</option><option value="cash">Cash purchase</option><option value="bank_finance">Bank finance</option><option value="mixed_finance">Mixed cash and bank finance</option><option value="developer_payment_plan">Developer payment plan</option><option value="other">Other funding</option></select></div><div><label>Property type applicability</label><select data-field="propertyType"><option value="all">All property types</option><option value="apartment">Apartment</option><option value="office">Office</option><option value="villa">Villa</option><option value="land">Land</option><option value="off_plan">Off-plan</option></select></div><div><label>Service channel</label><select data-field="serviceChannel"><option value="all">All/unspecified channels</option><option value="trustee_centre">Trustee centre</option><option value="dubai_now">Dubai Now</option><option value="dld_online">DLD online</option><option value="bank">Bank/lender</option><option value="other">Other</option></select></div><div><label>Usually paid by</label><select data-field="payer"><option value="contractual">As agreed/contractual</option><option value="buyer">Buyer</option><option value="seller">Seller</option><option value="shared">Shared</option><option value="lender">Lender-specific</option><option value="not_applicable">Not applicable</option></select></div><div class="span2"><label>Official source/reference</label><input data-field="sourceReference" value="${esc(f.sourceReference||'')}" placeholder="DLD service URL, circular or approved internal reference"></div><div><label><input data-field="includeInTotal" type="checkbox" ${f.includeInTotal===false?'':'checked'}> Include in calculated total</label></div><div class="span3" data-formula="conditional_fixed"><label>Conditional amount bands</label><div class="fee-bands"></div><button class="btn btn-sm" type="button" data-add-fee-band>Add condition band</button><small>Example: purchase price below 500000 = AED 2000; at or above 500000 = AED 4000. For property types use Equals and enter apartment,office.</small></div></div>`;for(const field of ['calculationType','calculationBasis','transactionType','fundingMethod','propertyType','serviceChannel','payer'])row.querySelector(`[data-field="${field}"]`).value=f[field]||({calculationType:'percentage',calculationBasis:'purchase_price',transactionType:'all',fundingMethod:'all',propertyType:'all',serviceChannel:'all',payer:'contractual'}[field]);const bands=row.querySelector('.fee-bands');for(const band of f.bands||[])addFeeBand(bands,band);row.querySelector('[data-remove-fee]').onclick=()=>row.remove();row.querySelector('[data-add-fee-band]').onclick=()=>addFeeBand(bands);row.querySelector('[data-field="calculationType"]').onchange=()=>refreshFeeItem(row);$('#fee-items').append(row);refreshFeeItem(row);}
function collectFeeItems(){const numeric=new Set(['ratePercent','amount','fixedAddition','capAmount','unitAmount','minAmount','maxAmount','vatPercent']);return Array.from(document.querySelectorAll('.fee-item')).map(row=>{const item={};row.querySelectorAll('.fee-rule-grid [data-field]').forEach(el=>item[el.dataset.field]=el.type==='checkbox'?el.checked:numeric.has(el.dataset.field)?(el.value===''?'':Number(el.value)):el.value);item.bands=Array.from(row.querySelectorAll('.fee-band')).map(b=>{const value=b.querySelector('[data-band-field="value"]').value,dimension=b.querySelector('[data-band-field="dimension"]').value;return{dimension,operator:b.querySelector('[data-band-field="operator"]').value,value:['purchase_price','mortgage_amount','property_value'].includes(dimension)?(value===''?'':Number(value)):value,amount:Number(b.querySelector('[data-band-field="amount"]').value)};});return item;});}
function fillAssumptionForm(v=null,{newVersion=false}={}){const form=$('#assumption-form'),editing=Boolean(v&&!newVersion);form.reset();form.classList.remove('hidden');$('#assumption-form-title').classList.remove('hidden');$('#assumption-new').classList.add('hidden');form.elements.id.value=editing?v.id:'';form.elements.name.value=v?.name||'Dubai property transaction costs';form.elements.currency.value=v?.currency||'AED';form.elements.sourceReference.value=v?.assumptions?.sourceReference||'';form.elements.disclaimer.value=v?.disclaimer||'Illustrative estimate only; regulatory, service-provider, lender and property-specific charges may differ and are subject to verification before transaction.';$('#fee-items').innerHTML='';for(const item of v?.assumptions?.items||[{code:'dld_transfer_fee',label:'DLD transfer fee',calculationType:'percentage',calculationBasis:'purchase_price',ratePercent:4,transactionType:'purchase',fundingMethod:'all',payer:'contractual'}])addFeeItem(item);$('#assumption-form-title').textContent=editing?`Edit draft · ${v.name} v${v.version}`:newVersion?`Create a new version from ${v.name} v${v.version}`:'Create a new draft rule set';$('#assumption-form-note').textContent=editing?'You are editing the selected draft. Save draft changes below; approved, active and retired versions remain unchanged.':newVersion?'A new draft will be created from this version. The source version remains unchanged.':'The fields below create a new draft. Saved versions in the table are read-only; use Edit draft or Create new version to make controlled changes.';$('#assumption-save').textContent=editing?'Save draft changes':newVersion?'Create new draft version':'Create draft rule set';form.scrollIntoView({behavior:'smooth',block:'start'});}
function closeAssumptionForm(){const form=$('#assumption-form');form.reset();form.elements.id.value='';form.classList.add('hidden');$('#assumption-form-title').classList.add('hidden');$('#assumption-new').classList.remove('hidden');$('#assumption-form-note').textContent='Saved versions are read-only. Select Edit draft, Create new version, or start a separate new rule set.';}
function feeRuleSummary(x={}){const formula=String(x.calculationType||'').replaceAll('_',' '),basis=String(x.calculationBasis||'none').replaceAll('_',' '),amount=x.calculationType==='percentage_plus_fixed'?`${x.ratePercent||0}% + ${x.fixedAddition||0}`:x.calculationType==='conditional_fixed'?(x.bands||[]).map(b=>`${String(b.dimension).replaceAll('_',' ')} ${String(b.operator).replaceAll('_',' ')} ${b.value}: ${b.amount}`).join('; '):x.calculationType==='quantity'?`${x.unitAmount} per ${x.quantityCode||'unit'}`:x.calculationType==='estimate_range'?`${x.minAmount}–${x.maxAmount}`:x.calculationType==='fixed'?`${x.amount}`:x.ratePercent!==undefined?`${x.ratePercent}%`:'amount not set';return`${formula} · ${amount||'amount not set'} · on ${basis} · VAT ${x.vatPercent||0}% · ${String(x.transactionType||'all').replaceAll('_',' ')} · funding: ${String(x.fundingMethod||'all').replaceAll('_',' ')} · ${String(x.propertyType||'all').replaceAll('_',' ')}`;}
function compareAssumptionVersion(current,versions){const prior=versions.filter(x=>x.name===current.name&&Number(x.version)<Number(current.version)).sort((a,b)=>Number(b.version)-Number(a.version))[0],currentRules=new Map((current.assumptions?.items||[]).map(x=>[x.code,x])),priorRules=new Map((prior?.assumptions?.items||[]).map(x=>[x.code,x])),codes=[...new Set([...priorRules.keys(),...currentRules.keys()])].sort();overlay(`<div class="modal lead-modal"><button class="close-x">×</button><h2>Fee rule-set changes · ${esc(current.name)} v${current.version}</h2>${prior?`<p class="tool-note">Compared with version ${prior.version}. This comparison explains business-rule changes; it does not alter either version.</p><table><tr><th>Rule</th><th>Version ${prior.version}</th><th>Version ${current.version}</th><th>Change</th></tr>${codes.map(code=>{const before=priorRules.get(code),after=currentRules.get(code),change=!before?'Added':!after?'Removed':JSON.stringify(before)===JSON.stringify(after)?'Unchanged':'Changed';return`<tr><td>${esc(after?.label||before?.label||code)}<small class="mono">fee.${esc(code)}</small></td><td>${before?esc(feeRuleSummary(before)):'—'}</td><td>${after?esc(feeRuleSummary(after)):'—'}</td><td>${change}</td></tr>`;}).join('')}</table><p><b>Authority/reference:</b> ${esc(prior.assumptions?.sourceReference||'—')} → ${esc(current.assumptions?.sourceReference||'—')}</p><p><b>Customer disclaimer:</b> ${esc(prior.disclaimer||'—')} → ${esc(current.disclaimer||'—')}</p>`:'<p>This is the first version of this rule set, so there is no earlier version to compare.</p>'}</div>`);}
