function renderProposalPropertyFields(fields){const chosen=new Map((fields||PROPOSAL_PROPERTY_FIELDS.map(([code,label,mandatory,condition])=>({code,label,mandatory,condition}))).map(x=>[x.code,x]));$('#proposal-property-fields').innerHTML=PROPOSAL_PROPERTY_FIELDS.map(([code,label,defaultMandatory,defaultCondition])=>{const f=chosen.get(code),condition=f?.condition||defaultCondition,mandatory=f?.mandatory??defaultMandatory;return `<div class="proposal-property-field" data-code="${code}"><label><input data-enabled type="checkbox" ${f?'checked':''}> ${esc(label)}</label><select data-condition>${PROPOSAL_CONDITIONS.map(([v,l])=>`<option value="${v}" ${v===condition?'selected':''}>${l}</option>`).join('')}</select><label><input data-mandatory type="checkbox" ${mandatory?'checked':''}> Mandatory</label></div>`;}).join('');}
