function fillProposalTemplateForm(t=null,newVersion=false){const form=$('#proposal-template-form'),c=t?.configuration||{},booklet=c.buyerBooklet||{};form.classList.remove('hidden');form.reset();form.elements.id.value=t&&!newVersion&&t.status==='draft'?t.id:'';form.elements.templateType.value=t?.templateType||'Quick';form.elements.templateType.disabled=Boolean(t);form.elements.name.value=t?.name||'NYSA Quick Buyer Booklet';form.elements.brandVersion.value=t?.brandVersion||organizationVersions.find(x=>x.status==='active')?.brandVersion||'';form.elements.maxProperties.value=booklet.maxProperties||3;form.elements.maxMediaPerProperty.value=booklet.maxMediaPerProperty??2;form.elements.maxAmenities.value=booklet.maxAmenities||5;form.elements.requireAvailabilityCheck.checked=booklet.requireAvailabilityCheck!==false;form.elements.approvedDisclaimers.value=(c.approvedDisclaimers||['Property availability, pricing and transaction timelines are indicative and must be reconfirmed before commitment.']).join('\n');$('#proposal-sections').innerHTML='';(c.sections?.length?c.sections:DEFAULT_PROPOSAL_SECTIONS).forEach(addProposalSection);renderProposalPropertyFields(booklet.propertyFields);$('#proposal-timeline-stages').innerHTML='';(booklet.timelineStages?.length?booklet.timelineStages:DEFAULT_PROPOSAL_TIMELINE).forEach(addProposalTimeline);$('#proposal-save').textContent=form.elements.id.value?`Save draft v${t.version}`:newVersion?`Create new version from v${t.version}`:'Create draft template';form.scrollIntoView({behavior:'smooth',block:'start'});}
